def destination_native_quota_manager_address(bridge: str) -> str:
    if not bridge:
        raise ValueError("destination Bridge address is empty")
    return f"{DESTINATION_NATIVE_QUOTA_MANAGER}:{bridge}"


def source_bundle_child_address(bundle_deployer: str, nonce: int) -> str:
    if (not bundle_deployer or type(nonce) is not int
            or nonce not in {1, 2, 3}):
        raise ValueError("source bundle child CREATE nonce is invalid")
    digest = keccak256(
        b"\xd6\x94" + _model_address20(bundle_deployer) + bytes((nonce,))
    )
    return "0x" + digest[-20:].hex()


def source_native_quota_manager_address(bundle_deployer: str) -> str:
    return source_bundle_child_address(bundle_deployer, 3)


def source_bridge_credit_registry_address(bundle_deployer: str) -> str:
    return source_bundle_child_address(bundle_deployer, 2)


def source_terminal_verifier_configuration_hash(
    *, router_address: str,
) -> str:
    if not router_address:
        raise ValueError("source terminal verifier configuration is incomplete")
    config = _model_address20(router_address) + _model_uint(
        64, 1, "terminal tree depth"
    )
    if len(config) != 21:
        raise AssertionError("terminal verifier component config drifted")
    return keccak256(b"".join((
        b"slot-chain-component-config-v1",
        _model_uint(3, 1, "terminal verifier component kind"),
        _model_uint(len(config), 2, "terminal verifier config length"),
        config,
    ))).hex()


def source_bridge_create2_address(
    factory: str, salt: str, initcode_hash: str,
) -> str:
    """Derive the exact Ethereum CREATE2 address from the pinned tuple."""

    if any(type(word) is not str or not word for word in (
        factory, salt, initcode_hash,
    )):
        raise ValueError("CREATE2 source Bridge tuple is incomplete")
    digest = keccak256(b"".join((
        b"\xff",
        _model_address20(factory),
        _model_fixed_bytes32(salt),
        _model_fixed_bytes32(initcode_hash),
    )))
    return "0x" + digest[-20:].hex()


def bridge_adapter_create2_salt_v1(
    protocol_version: int, source_descriptor_id: str | bytes,
) -> bytes:
    """Derive the unique per-release adapter salt without its own address."""

    return keccak256(
        b"slot-chain-bridge-adapter-salt-v1"
        + _model_uint(protocol_version, 8, "adapter protocol version")
        + _model_fixed_bytes32(source_descriptor_id)
    )


def bridge_adapter_initcode_hash_v1(
    *, configuration_hash: str | bytes, source_bridge: str,
    credit_registry: str, router: str, queue: str, seal_authority: str,
) -> bytes:
    """Hash the pinned creation artifact and canonical constructor ABI."""

    constructor_abi = b"".join((
        _model_fixed_bytes32(configuration_hash),
        bytes(12) + _model_address20(source_bridge),
        bytes(12) + _model_address20(credit_registry),
        bytes(12) + _model_address20(router),
        bytes(12) + _model_address20(queue),
        bytes(12) + _model_address20(seal_authority),
    ))
    if len(constructor_abi) != 192:
        raise AssertionError("Bridge adapter constructor ABI width drifted")
    return keccak256(BRIDGE_ADAPTER_CREATION_CODE_V1 + constructor_abi)


def bridge_adapter_create2_address_v1(
    *, factory: str, protocol_version: int,
    source_descriptor_id: str | bytes, configuration_hash: str | bytes,
    source_bridge: str, credit_registry: str, router: str, queue: str,
    seal_authority: str,
) -> str:
    salt = bridge_adapter_create2_salt_v1(
        protocol_version, source_descriptor_id)
    initcode_hash = bridge_adapter_initcode_hash_v1(
        configuration_hash=configuration_hash,
        source_bridge=source_bridge, credit_registry=credit_registry,
        router=router, queue=queue, seal_authority=seal_authority,
    )
    return source_bridge_create2_address(
        factory, salt.hex(), initcode_hash.hex())


def exact_component_config_staticcall(
    component: object, *, expected_runtime_hash: str | bytes,
    expected_configuration_hash: str | bytes,
) -> bool:
    """Model the exact four-byte/50k/32-byte configuration read boundary."""

    if (not expected_runtime_hash or not expected_configuration_hash
            or _model_fixed_bytes32(
                getattr(component, "runtime_hash", "")
            ) != _model_fixed_bytes32(expected_runtime_hash)
            or _model_fixed_bytes32(
                getattr(component, "configuration_hash", "")
            ) != _model_fixed_bytes32(expected_configuration_hash)
            or getattr(component, "component_config_call_fault", False)):
        return False
    calldata = COMPONENT_CONFIG_GETTER_SELECTOR
    gas = COMPONENT_CONFIG_GETTER_GAS
    if len(calldata) != 4 or gas != 50_000:
        raise AssertionError("componentConfigHashV2 call geometry drifted")
    override = getattr(component, "component_config_return_override", None)
    returndata = (
        _model_fixed_bytes32(expected_configuration_hash)
        if override is None else override
    )
    return (
        type(returndata) is bytes
        and len(returndata) == 32
        and returndata == _model_fixed_bytes32(expected_configuration_hash)
    )


def inbox_apply_deployment_descriptor_hash_v1(
    *, address: str, registrar_address: str,
    runtime_hash: str | bytes, configuration_hash: str | bytes,
) -> bytes:
    payload = b"".join((
        _model_address20(address), _model_address20(registrar_address),
        _model_fixed_bytes32(runtime_hash),
        _model_fixed_bytes32(configuration_hash),
    ))
    if len(payload) != 104:
        raise AssertionError("InboxApply deployment descriptor width drifted")
    return keccak256(
        b"slot-chain-inbox-apply-deployment-descriptor-v1"
        + _model_uint(len(payload), 2, "InboxApply descriptor bytes")
        + payload
    )


