def active_settlement_router_configuration_hash_v2(
    *, settlement_chain_context_id: int,
    version_manager: str, version_manager_runtime_hash: str | bytes,
    forced_queue_address: str, forced_queue_runtime_hash: str | bytes,
    forced_queue_configuration_hash: str | bytes,
    builder_registry_address: str, schedule_oracle_address: str,
    router_namespace: bytes, inbox_apply_descriptor_hash: bytes,
    l1_history_first_supported_block: int,
    l1_history_read_configuration_hash: bytes,
    legacy_bootstrap_descriptor_hash: bytes,
) -> bytes:
    if (type(settlement_chain_context_id) is not int
            or not 0 < settlement_chain_context_id <= SEAT_UINT256_MAX
            or type(l1_history_first_supported_block) is not int
            or not 0 < l1_history_first_supported_block <= UINT64_MAX):
        raise ValueError("Router chain/history bound is unsupported")
    payload = b"".join((
        _model_uint(settlement_chain_context_id, 32, "Router chain"),
        _model_address20(version_manager),
        _model_fixed_bytes32(version_manager_runtime_hash),
        _model_address20(forced_queue_address),
        _model_fixed_bytes32(forced_queue_runtime_hash),
        _model_fixed_bytes32(forced_queue_configuration_hash),
        _model_address20(builder_registry_address),
        _model_address20(schedule_oracle_address),
        _model_fixed_bytes32(router_namespace),
        _model_fixed_bytes32(inbox_apply_descriptor_hash),
        _model_uint(
            l1_history_first_supported_block, 8,
            "Router first supported L1 block",
        ),
        _model_fixed_bytes32(l1_history_read_configuration_hash),
        _model_fixed_bytes32(legacy_bootstrap_descriptor_hash),
    ))
    if len(payload) != 344:
        raise AssertionError("ActiveSettlementRouter config width drifted")
    return keccak256(
        D_COMPONENT_CONFIG + _model_uint(2, 1, "Router component kind")
        + _model_uint(len(payload), 2, "Router configuration bytes")
        + payload
    )


def bridge_ingress_component_configuration_hash(
    *,
    router_address: str,
    router_runtime_hash: str,
    router_configuration_hash: str,
    queue_address: str,
    queue_runtime_hash: str,
    queue_configuration_hash: str,
    source_registry_address: str,
    source_registry_runtime_hash: str,
    source_registry_configuration_hash: str,
    source_bridge_address: str,
    source_bridge_runtime_hash: str,
    source_bridge_configuration_hash_: str,
    seal_authority: str,
) -> str:
    """Commit the exact acyclic kind-1 constructor graph."""

    words = (
        router_address, router_runtime_hash, router_configuration_hash,
        queue_address, queue_runtime_hash, queue_configuration_hash,
        source_registry_address, source_registry_runtime_hash,
        source_registry_configuration_hash, source_bridge_address,
        source_bridge_runtime_hash, source_bridge_configuration_hash_,
        seal_authority,
    )
    if any(type(word) is not str or not word for word in words):
        raise ValueError("Bridge ingress configuration is incomplete")
    # Runtime/code identities are independently exact-read.  Repeating them
    # here formerly produced a second, incompatible configuration schema.
    # These five addresses are the complete constructor authority surface.
    config = b"".join((
        _model_address20(source_registry_address),
        _model_address20(source_bridge_address),
        _model_address20(router_address),
        _model_address20(queue_address),
        _model_address20(seal_authority),
    ))
    if len(config) != 100:
        raise AssertionError("Bridge ingress component config drifted")
    return "0x" + keccak256(b"".join((
        D_COMPONENT_CONFIG,
        _model_uint(1, 1, "Bridge ingress component kind"),
        _model_uint(len(config), 2, "Bridge ingress config bytes"),
        config,
    ))).hex()


def bridge_credit_registry_configuration_hash(
    *, address: str, runtime_hash: str, domain_registrar: str,
    frozen_bridge: str, support_registry_address: str,
    support_registry_runtime_hash: str,
    support_registry_configuration_hash: str,
    source_chain_id: int, source_domain_id: str,
    source_registration_epoch: int,
    frozen_bridge_execution_hash: str,
    source_descriptor_id: bytes,
) -> str:
    if (type(source_descriptor_id) is not bytes
            or len(source_descriptor_id) != 32
            or not 0 < source_chain_id <= UINT64_MAX
            or not 0 < source_registration_epoch <= UINT64_MAX
            or not source_domain_id or not frozen_bridge_execution_hash):
        raise ValueError("source Bridge descriptor id is not bytes32")
    # Constructor identity is deliberately acyclic.  The derived domain,
    # execution hash and descriptor id are installed and exact-read as
    # activation state; including them here would make the descriptor commit
    # its own hash.  Runtime identity is checked independently by EXTCODEHASH.
    static = (
        address, runtime_hash, domain_registrar, frozen_bridge,
        support_registry_address, support_registry_runtime_hash,
        support_registry_configuration_hash,
    )
    if any(type(word) is not str or not word for word in static):
        raise ValueError("Bridge credit registry configuration is incomplete")
    encoded = b"".join((
        b"slot-chain-source-credit-registry-config-v2",
        _model_address20(address), _model_address20(domain_registrar),
        _model_address20(frozen_bridge),
        _model_address20(support_registry_address),
        _model_fixed_bytes32(support_registry_runtime_hash),
        _model_fixed_bytes32(support_registry_configuration_hash),
    ))
    return "0x" + keccak256(encoded).hex()


def bridge_domain_registry_configuration_hash(
    *, address: str, runtime_hash: str, support_authority: str,
    router_address: str, router_runtime_hash: str,
    router_configuration_hash: str, release_authority_address: str,
    release_authority_runtime_hash: str,
    release_authority_configuration_hash: str,
    registration_mpt_verifier_descriptor_hash: str,
) -> str:
    words = (
        address, runtime_hash, support_authority, router_address,
        router_runtime_hash, router_configuration_hash,
        release_authority_address, release_authority_runtime_hash,
        release_authority_configuration_hash,
        registration_mpt_verifier_descriptor_hash,
    )
    if any(type(word) is not str or not word for word in words):
        raise ValueError("Bridge support registry configuration is incomplete")
    encoded = b"".join((
        _model_address20(address), _model_fixed_bytes32(runtime_hash),
        _model_address20(support_authority), _model_address20(router_address),
        _model_fixed_bytes32(router_runtime_hash),
        _model_fixed_bytes32(router_configuration_hash),
        _model_address20(release_authority_address),
        _model_fixed_bytes32(release_authority_runtime_hash),
        _model_fixed_bytes32(release_authority_configuration_hash),
        _model_fixed_bytes32(registration_mpt_verifier_descriptor_hash),
    ))
    if len(encoded) != 272:
        raise AssertionError("Bridge support registry config width drifted")
    return "0x" + keccak256(
        b"slot-chain-bridge-domain-registry-config-v2"
        + _model_uint(len(encoded), 2, "support registry config bytes")
        + encoded
    ).hex()


def registration_mpt_verifier_configuration_hash(
    *,
    public_input_schema_hash: str = REGISTRATION_MPT_PUBLIC_INPUT_SCHEMA_HASH,
    proof_schema_hash: str = REGISTRATION_MPT_PROOF_SCHEMA_HASH,
    selector: bytes = REGISTRATION_MPT_VERIFIER_SELECTOR_BYTES,
    maximum_path_nodes: int = MAX_REGISTRATION_PROOF_PATH_NODES,
    maximum_nodes: int = MAX_REGISTRATION_PROOF_NODES,
    maximum_node_bytes: int = MAX_REGISTRATION_PROOF_NODE_BYTES,
    maximum_total_bytes: int = MAX_REGISTRATION_PROOF_BYTES,
    verification_gas_limit: int = REGISTRATION_MPT_VERIFIER_GAS_LIMIT,
) -> str:
    if (type(selector) is not bytes or len(selector) != 4
            or public_input_schema_hash
                != REGISTRATION_MPT_PUBLIC_INPUT_SCHEMA_HASH
            or proof_schema_hash != REGISTRATION_MPT_PROOF_SCHEMA_HASH
            or maximum_path_nodes != MAX_REGISTRATION_PROOF_PATH_NODES
            or maximum_nodes != MAX_REGISTRATION_PROOF_NODES
            or maximum_node_bytes != MAX_REGISTRATION_PROOF_NODE_BYTES
            or maximum_total_bytes != MAX_REGISTRATION_PROOF_BYTES
            or verification_gas_limit != REGISTRATION_MPT_VERIFIER_GAS_LIMIT):
        raise ValueError("registration MPT verifier configuration is incomplete")
    encoded = b"".join((
        REGISTRATION_MPT_VERIFIER_CONFIG_TYPEHASH,
        bytes.fromhex(public_input_schema_hash),
        bytes.fromhex(proof_schema_hash),
        selector + bytes(28),
        _model_uint(maximum_path_nodes, 32, "maximum nodes per path"),
        _model_uint(maximum_nodes, 32, "maximum total nodes"),
        _model_uint(maximum_node_bytes, 32, "maximum node bytes"),
        _model_uint(maximum_total_bytes, 32, "maximum proof bytes"),
        _model_uint(verification_gas_limit, 32, "verification gas limit"),
    ))
    if len(encoded) != 9 * 32:
        raise AssertionError("registration verifier config ABI width drifted")
    return keccak256(encoded).hex()

MAX_LIABILITY_RESIDENCE_WINDOWS = (
    MAX_TRANCHE_AHEAD_WINDOWS + 1
    + (EVIDENCE_DELAY_SECONDS + REORG_MARGIN_SECONDS + 383) // 384 + 2
)
RESERVATION_EVIDENCE_RETENTION_WINDOWS = (
    1 + (EVIDENCE_DELAY_SECONDS + REORG_MARGIN_SECONDS + 383) // 384 + 2
)


class Mode(Enum):
    PREACTIVE = auto()
    NORMAL = auto()
    RECOVERY = auto()


class Cause(IntFlag):
    NONE = 0
    SLA = 1
    FORCE_DUE = 2


@dataclass(frozen=True)
class SystemTransactionV2:
    tx_type: int
    chain_id: int
    system_kind: int
    system_nonce: int
    gas_limit: int
    to: str
    value: int
    selector: str
    signed: bool = False

    def valid(self, *, block_number: int, first_v2_block_number: int,
              launch_imported_l2_block_number: int,
              first_activation: bool, l2_chain_id: int,
              anchor_address: str = "anchor:v2",
              inbox_apply_address: str = "inbox-apply") -> bool:
        if self.system_kind == SYSTEM_KIND_ANCHOR:
            expected_selector = (ANCHOR_ACTIVATION_SELECTOR if first_activation
                                 else ANCHOR_STEADY_SELECTOR)
            expected_gas = (ANCHOR_ACTIVATION_GAS_MAX if first_activation
                            else ANCHOR_GAS_MAX)
            expected_to = anchor_address
        elif self.system_kind == SYSTEM_KIND_INBOX_APPLY:
            expected_selector = INBOX_APPLY_SELECTOR
            expected_gas = INBOX_APPLY_GAS_MAX
            expected_to = inbox_apply_address
        else:
            return False
        return (self.tx_type == SYSTEM_TX_TYPE
                and self.chain_id == l2_chain_id
                and 0 < l2_chain_id <= UINT64_MAX
                and first_v2_block_number
                    == launch_imported_l2_block_number + 1
                and self.system_nonce
                    == block_number - first_v2_block_number
                and block_number >= first_v2_block_number
                and self.gas_limit == expected_gas
                and self.to == expected_to and self.value == 0
                and self.selector == expected_selector and not self.signed)


@dataclass(frozen=True)
class SystemExecutionRulesV2:
    """Consensus effects not inherited from any ordinary account transaction."""

    reserved_sender: str
    caller: str
    origin: str
    sender_nonce_before: int
    sender_nonce_after: int
    sender_balance_before: int
    sender_balance_after: int
    gas_price_opcode: int
    zero_calldata_bytes: int
    nonzero_calldata_bytes: int
    intrinsic_gas: int
    sender_warm: bool
    target_warm: bool
    typed_tx_trie_value: bool
    typed_receipt_trie_value: bool

    def valid(self, tx: SystemTransactionV2) -> bool:
        expected_intrinsic = (21_000 + 4 * self.zero_calldata_bytes
                              + 16 * self.nonzero_calldata_bytes)
        return (self.caller == self.reserved_sender
                and self.origin == self.reserved_sender
                and self.sender_nonce_after == self.sender_nonce_before
                and self.sender_balance_after == self.sender_balance_before
                and self.gas_price_opcode == 0
                and self.zero_calldata_bytes >= 0
                and self.nonzero_calldata_bytes >= 4
                and self.intrinsic_gas == expected_intrinsic
                and self.intrinsic_gas <= tx.gas_limit
                and self.sender_warm and self.target_warm
                and self.typed_tx_trie_value
                and self.typed_receipt_trie_value)


@dataclass
class L2ActivationLatch:
    active: bool = False

    def activate_from_anchor(self, *, custom_system_tx: bool,
                             slot_chain_fork_active: bool,
                             l1_cutover_authenticated: bool) -> bool:
        if (self.active or not custom_system_tx or not slot_chain_fork_active
                or not l1_cutover_authenticated):
            return False
        self.active = True
        return True

    def inbox_apply(self, *, custom_system_tx: bool) -> bool:
        return self.active and custom_system_tx

    def bridge_v2_call(self) -> bool:
        return self.active


