def _migration_u64(value: int, name: str) -> bytes:
    value = seat_u256(value, name)
    if value > UINT64_MAX:
        raise ValueError(f"{name} is outside uint64")
    return value.to_bytes(8, "big")


def encode_seat_migration_response(response: SeatMigrationResponse) -> bytes:
    if type(response) is not SeatMigrationResponse:
        raise ValueError("malformed seat migration response")
    if response.magic not in (SEAT_ARMED_MAGIC, SEAT_ABORTED_MAGIC):
        raise ValueError("unknown seat migration response magic")
    if (
        type(response.target_manifest_hash) is not bytes
        or len(response.target_manifest_hash) != 32
        or type(response.target_registration_hash) is not bytes
        or len(response.target_registration_hash) != 32
    ):
        raise ValueError("migration manifest must be exact bytes32")
    payload = b"".join((
        response.magic,
        _migration_u64(response.router_generation, "router generation"),
        _migration_u64(response.active_protocol_version, "active protocol version"),
        _migration_u64(response.target_protocol_version, "target protocol version"),
        response.target_manifest_hash,
        response.target_registration_hash,
        _migration_u64(response.seat_generation, "seat generation"),
    ))
    if len(payload) != SEAT_MIGRATION_RESPONSE_PAYLOAD_LENGTH:
        raise AssertionError("seat migration payload width drifted")
    return b"".join((
        _model_uint(0x20, 32, "seat response offset"),
        _model_uint(len(payload), 32, "seat response length"),
        payload,
        bytes(28),
    ))


def decode_seat_migration_response(raw: bytes) -> SeatMigrationResponse:
    if type(raw) is not bytes or len(raw) != SEAT_MIGRATION_RESPONSE_LENGTH:
        raise ValueError("seat migration response has noncanonical length")
    if (raw[:32] != _model_uint(0x20, 32, "seat response offset")
            or raw[32:64] != _model_uint(
                SEAT_MIGRATION_RESPONSE_PAYLOAD_LENGTH, 32,
                "seat response length",
            )
            or raw[-28:] != bytes(28)):
        raise ValueError("seat migration response ABI is noncanonical")
    payload = raw[64:164]
    magic = payload[:4]
    if magic not in (SEAT_ARMED_MAGIC, SEAT_ABORTED_MAGIC):
        raise ValueError("seat migration response has wrong magic")
    return SeatMigrationResponse(
        magic,
        int.from_bytes(payload[4:12], "big"),
        int.from_bytes(payload[12:20], "big"),
        int.from_bytes(payload[20:28], "big"),
        payload[28:60],
        payload[60:92],
        int.from_bytes(payload[92:100], "big"),
    )


@dataclass(frozen=True)
class Generation:
    address: str
    bond: int
    registration_index: int
    effective_window: int
    max_reserved_window: int = 0
    reservations_closed: bool = False
    tombstoned_at_l2_slot: int = UINT64_MAX
    reservation_base_window: int = 0
    reservation_bitmap: int = 0
    unreleased_tranche_count: int = 0
    maximum_liable_until: int = 0
    exit_sequence: int | None = None
    effective_l2_slot: int | None = None


def builder_admission_leaf_hash_v1(
    position: int, location: int, builder: object, bond: int,
    registration_index: int, effective_l2_slot: int,
    tombstoned_at_l2_slot: int,
) -> bytes:
    if (not 0 <= position < 2_048 or location not in {1, 2}
            or (location == 1 and position >= MAX_BUILDERS)
            or (location == 2 and not MAX_BUILDERS <= position
                < MAX_BUILDERS + MAX_LIABILITY_GENERATIONS)):
        raise ValueError("builder admission position/location is invalid")
    builder_address = _model_address20(builder)
    if (builder_address == bytes(20) or not 0 < bond < 1 << 192
            or not 0 <= registration_index <= UINT64_MAX
            or not 0 <= effective_l2_slot <= UINT64_MAX
            or not 0 <= tombstoned_at_l2_slot <= UINT64_MAX):
        raise ValueError("builder admission identity is invalid")
    return keccak256(b"".join((
        b"slot-chain-admission-leaf-v1",
        _model_uint(position, 2, "builder admission position"),
        b"\x01", bytes((location,)), builder_address,
        _model_uint(bond, 24, "builder admission bond"),
        _model_uint(registration_index, 8, "builder registration index"),
        _model_uint(effective_l2_slot, 8, "builder effective L2 slot"),
        _model_uint(
            tombstoned_at_l2_slot, 8, "builder tombstone L2 slot"
        ),
    )))


def historical_evidence_admission_leaf_hash_v1(
    position: int, generation: Generation,
) -> bytes:
    if (type(generation) is not Generation
            or generation.effective_l2_slot is None):
        raise ValueError("historical evidence generation is invalid")
    location = 1 if position < MAX_BUILDERS else 2
    return builder_admission_leaf_hash_v1(
        position, location, generation.address, generation.bond,
        generation.registration_index, generation.effective_l2_slot,
        UINT64_MAX,
    )


