@dataclass(frozen=True)
class ActiveBridgeRouteV2:
    active_protocol_version: int
    source_chain_id: int
    source_registration_epoch: int
    source_domain_id: bytes
    bridge_execution_hash: bytes
    destination_domain_id: bytes
    destination_bridge: bytes
    release_manifest_hash: bytes
    execution_profile_hash: bytes
    invocation_policy_hash: bytes
    checked_target: bytes


def encode_active_bridge_route_v2(route: ActiveBridgeRouteV2) -> bytes:
    if (type(route) is not ActiveBridgeRouteV2
            or any(type(value) is not bytes or len(value) != 32
                   or value == bytes(32) for value in (
                       route.source_domain_id, route.bridge_execution_hash,
                       route.destination_domain_id,
                       route.release_manifest_hash,
                       route.execution_profile_hash,
                       route.invocation_policy_hash,
                   ))
            or type(route.destination_bridge) is not bytes
            or len(route.destination_bridge) != 20
            or route.destination_bridge == bytes(20)
            or type(route.checked_target) is not bytes
            or len(route.checked_target) != 20
            or route.checked_target == bytes(20)):
        raise ValueError("active Bridge route is malformed")
    encoded = b"".join((
        ACTIVE_BRIDGE_ROUTE_MAGIC + bytes(28),
        _model_uint(route.active_protocol_version, 32, "ABR2 version"),
        _model_uint(route.source_chain_id, 32, "ABR2 source chain"),
        _model_uint(route.source_registration_epoch, 32, "ABR2 source epoch"),
        route.source_domain_id, route.bridge_execution_hash,
        route.destination_domain_id,
        bytes(12) + route.destination_bridge,
        route.release_manifest_hash, route.execution_profile_hash,
        route.invocation_policy_hash,
        bytes(12) + route.checked_target,
    ))
    if len(encoded) != ACTIVE_BRIDGE_ROUTE_RETURN_LENGTH:
        raise AssertionError("ABR2 return width drifted")
    return encoded


def decode_active_bridge_route_v2(raw: bytes) -> ActiveBridgeRouteV2:
    if type(raw) is not bytes or len(raw) != ACTIVE_BRIDGE_ROUTE_RETURN_LENGTH:
        raise ValueError("ABR2 return length is invalid")
    words = tuple(raw[index:index + 32]
                  for index in range(0, len(raw), 32))
    if (words[0] != ACTIVE_BRIDGE_ROUTE_MAGIC + bytes(28)
            or words[7][:12] != bytes(12)
            or words[11][:12] != bytes(12)):
        raise ValueError("ABR2 magic or address padding is invalid")
    route = ActiveBridgeRouteV2(
        _decode_uint_word_v1(words[1], 64, "ABR2 version"),
        _decode_uint_word_v1(words[2], 64, "ABR2 source chain"),
        _decode_uint_word_v1(words[3], 64, "ABR2 source epoch"),
        words[4], words[5], words[6], words[7][12:], words[8], words[9],
        words[10], words[11][12:],
    )
    if encode_active_bridge_route_v2(route) != raw:
        raise ValueError("ABR2 return is noncanonical")
    return route


@dataclass(frozen=True)
class DestinationReleaseAuthorityDescriptor:
    """L1 commitment to the destination authority, never a live L2 object."""

    destination_chain_id: int
    authority_address: str
    authority_runtime_hash: str
    authority_configuration_hash: str
    registrar_address: str
    registrar_runtime_hash: str
    registrar_configuration_hash: str
    registration_slot_schema_hash: str

    def structurally_valid(self) -> bool:
        return (
            0 < self.destination_chain_id <= UINT64_MAX
            and all((
                self.authority_address,
                self.authority_runtime_hash,
                self.authority_configuration_hash,
                self.registrar_address,
                self.registrar_runtime_hash,
                self.registrar_configuration_hash,
                self.registration_slot_schema_hash,
            ))
        )


@dataclass(frozen=True)
class RegistrationMptVerifierDescriptor:
    """Immutable parser/verifier identity for destination registration proofs."""

    address: str
    runtime_hash: str
    configuration_hash: str
    public_input_schema_hash: str
    selector: bytes
    proof_schema_hash: str
    maximum_path_nodes: int
    maximum_nodes: int
    maximum_node_bytes: int
    maximum_total_bytes: int
    verification_gas_limit: int
    nonproxy: bool = True

    @property
    def commitment(self) -> str:
        encoded = b"".join((
            REGISTRATION_MPT_VERIFIER_DESCRIPTOR_TYPEHASH,
            bytes(12) + _model_address20(self.address),
            _model_fixed_bytes32(self.runtime_hash),
            bytes.fromhex(self.configuration_hash),
            bytes.fromhex(self.public_input_schema_hash),
            bytes.fromhex(self.proof_schema_hash),
            self.selector + bytes(28),
            _model_uint(self.maximum_path_nodes, 32,
                        "maximum nodes per path"),
            _model_uint(self.maximum_nodes, 32, "maximum total nodes"),
            _model_uint(self.maximum_node_bytes, 32, "maximum node bytes"),
            _model_uint(self.maximum_total_bytes, 32, "maximum proof bytes"),
            _model_uint(self.verification_gas_limit, 32,
                        "verification gas limit"),
        ))
        if len(encoded) != 12 * 32:
            raise AssertionError("registration verifier descriptor ABI drifted")
        return keccak256(encoded).hex()

    def structurally_valid(self) -> bool:
        return (
            self.address == REGISTRATION_MPT_VERIFIER_ADDRESS
            and self.runtime_hash == REGISTRATION_MPT_VERIFIER_RUNTIME_HASH
            and self.selector == REGISTRATION_MPT_VERIFIER_SELECTOR_BYTES
            and self.public_input_schema_hash
                == REGISTRATION_MPT_PUBLIC_INPUT_SCHEMA_HASH
            and self.proof_schema_hash == REGISTRATION_MPT_PROOF_SCHEMA_HASH
            and self.maximum_path_nodes
                == MAX_REGISTRATION_PROOF_PATH_NODES
            and self.maximum_nodes == MAX_REGISTRATION_PROOF_NODES
            and self.maximum_node_bytes
                == MAX_REGISTRATION_PROOF_NODE_BYTES
            and self.maximum_total_bytes == MAX_REGISTRATION_PROOF_BYTES
            and self.verification_gas_limit
                == REGISTRATION_MPT_VERIFIER_GAS_LIMIT
            and self.nonproxy
            and self.configuration_hash
                == registration_mpt_verifier_configuration_hash(
                    public_input_schema_hash=self.public_input_schema_hash,
                    proof_schema_hash=self.proof_schema_hash,
                    selector=self.selector,
                    maximum_path_nodes=self.maximum_path_nodes,
                    maximum_nodes=self.maximum_nodes,
                    maximum_node_bytes=self.maximum_node_bytes,
                    maximum_total_bytes=self.maximum_total_bytes,
                    verification_gas_limit=self.verification_gas_limit,
                )
        )


def canonical_registration_mpt_verifier_descriptor(
) -> RegistrationMptVerifierDescriptor:
    descriptor = RegistrationMptVerifierDescriptor(
        REGISTRATION_MPT_VERIFIER_ADDRESS,
        REGISTRATION_MPT_VERIFIER_RUNTIME_HASH,
        registration_mpt_verifier_configuration_hash(),
        REGISTRATION_MPT_PUBLIC_INPUT_SCHEMA_HASH,
        REGISTRATION_MPT_VERIFIER_SELECTOR_BYTES,
        REGISTRATION_MPT_PROOF_SCHEMA_HASH,
        MAX_REGISTRATION_PROOF_PATH_NODES,
        MAX_REGISTRATION_PROOF_NODES,
        MAX_REGISTRATION_PROOF_NODE_BYTES,
        MAX_REGISTRATION_PROOF_BYTES,
        REGISTRATION_MPT_VERIFIER_GAS_LIMIT,
    )
    if not descriptor.structurally_valid():
        raise AssertionError("canonical registration MPT verifier is invalid")
    return descriptor


def terminal_registration_storage_slot(protocol_version: int) -> str:
    """Exact Solidity mapping slot for registrationCommitment[version]."""

    if type(protocol_version) is not int or not 0 < protocol_version <= UINT64_MAX:
        raise ValueError("registration storage-slot version is invalid")
    base_slot = keccak256(
        b"slot-chain-terminal-domain-registrar.registrationCommitment.v1"
    )
    return keccak256(protocol_version.to_bytes(32, "big") + base_slot).hex()


def terminal_registration_storage_trie_key(protocol_version: int) -> str:
    return keccak256(
        bytes.fromhex(terminal_registration_storage_slot(protocol_version))
    ).hex()


def registration_route_key(
    source_domain_id: str,
    bridge_execution_hash: str,
    destination_domain_id: str,
) -> str:
    if not source_domain_id or not bridge_execution_hash or not destination_domain_id:
        raise ValueError("registration route key is incomplete")
    return keccak256(b"".join((
        REGISTRATION_ROUTE_KEY_TYPEHASH,
        _model_fixed_bytes32(source_domain_id),
        _model_fixed_bytes32(bridge_execution_hash),
        _model_fixed_bytes32(destination_domain_id),
    ))).hex()


@dataclass(frozen=True)
class RegistrationStorageStatement:
    settlement_chain_id: int
    active_settlement_router: str
    bridge_domain_registry: str
    route_key: str
    destination_chain_id: int
    protocol_version: int
    canonical_sequence: int
    state_root: str
    terminal_domain_registrar: str
    registrar_code_hash: str
    storage_trie_key: str
    expected_value: bytes

    def __post_init__(self) -> None:
        if (not 0 < self.settlement_chain_id <= SEAT_UINT256_MAX
                or not 0 < self.destination_chain_id <= SEAT_UINT256_MAX
                or not 0 < self.protocol_version <= UINT64_MAX
                or not 0 <= self.canonical_sequence <= UINT64_MAX
                or any(type(word) is not str or not word for word in (
                    self.active_settlement_router,
                    self.bridge_domain_registry,
                    self.route_key,
                    self.state_root,
                    self.terminal_domain_registrar,
                    self.registrar_code_hash,
                    self.storage_trie_key,
                ))
                or self.storage_trie_key
                    != terminal_registration_storage_trie_key(
                        self.protocol_version
                    )
                or type(self.expected_value) is not bytes
                or len(self.expected_value) != 32
                or self.expected_value == bytes(32)):
            raise ValueError("registration storage statement is invalid")

    @property
    def abi_words(self) -> tuple[bytes, ...]:
        return (
            _model_uint(self.settlement_chain_id, 32, "settlement chain id"),
            bytes(12) + _model_address20(self.active_settlement_router),
            bytes(12) + _model_address20(self.bridge_domain_registry),
            bytes.fromhex(self.route_key),
            _model_uint(self.destination_chain_id, 32, "destination chain id"),
            _model_uint(self.protocol_version, 32, "protocol version"),
            _model_uint(self.canonical_sequence, 32, "canonical sequence"),
            _model_fixed_bytes32(self.state_root),
            bytes(12) + _model_address20(self.terminal_domain_registrar),
            _model_fixed_bytes32(self.registrar_code_hash),
            bytes.fromhex(self.storage_trie_key),
            self.expected_value,
        )

    @property
    def digest(self) -> str:
        return keccak256(
            REGISTRATION_STORAGE_STATEMENT_TYPEHASH
            + b"".join(self.abi_words)
        ).hex()


@dataclass(frozen=True)
class CanonicalMptMembershipProof:
    """Raw ordered MPT nodes; the seal exists only in the test verifier mock."""

    account_nodes: tuple[bytes, ...]
    storage_nodes: tuple[bytes, ...]
    _test_seal: str = field(default="", repr=False, compare=False)

    @property
    def canonical_bytes(self) -> bytes:
        nodes = self.account_nodes + self.storage_nodes
        if (not self.account_nodes or not self.storage_nodes
                or len(self.account_nodes) > MAX_REGISTRATION_PROOF_PATH_NODES
                or len(self.storage_nodes) > MAX_REGISTRATION_PROOF_PATH_NODES
                or len(nodes) > MAX_REGISTRATION_PROOF_NODES
                or any(type(node) is not bytes
                       or not 0 < len(node) <= MAX_REGISTRATION_PROOF_NODE_BYTES
                       for node in nodes)):
            raise ValueError("registration MPT proof nodes are noncanonical")
        encoded = (
            len(self.account_nodes).to_bytes(2, "big")
            + len(self.storage_nodes).to_bytes(2, "big")
            + b"".join(len(node).to_bytes(2, "big") + node for node in nodes)
        )
        if len(encoded) > MAX_REGISTRATION_PROOF_BYTES:
            raise ValueError("registration MPT proof encoding is too large")
        return encoded


def registration_verifier_calldata(
    statement: RegistrationStorageStatement,
    proof: CanonicalMptMembershipProof,
) -> bytes:
    if (type(statement) is not RegistrationStorageStatement
            or type(proof) is not CanonicalMptMembershipProof):
        raise ValueError("registration verifier calldata inputs are invalid")
    proof_bytes = proof.canonical_bytes
    padded_length = (len(proof_bytes) + 31) // 32 * 32
    calldata = b"".join((
        REGISTRATION_MPT_VERIFIER_SELECTOR_BYTES,
        *statement.abi_words,
        _model_uint(13 * 32, 32, "registration proof ABI offset"),
        _model_uint(len(proof_bytes), 32, "registration proof byte length"),
        proof_bytes,
        bytes(padded_length - len(proof_bytes)),
    ))
    expected = 4 + 13 * 32 + 32 + padded_length
    if len(calldata) != expected:
        raise AssertionError("registration verifier ABI geometry drifted")
    return calldata


_REGISTRATION_MPT_RESULT_CAPABILITY = object()


@dataclass(frozen=True, eq=False)
class VerifiedRegistrationMembership:
    verifier: "IRegistrationMptVerifier" = field(compare=False, repr=False)
    descriptor: RegistrationMptVerifierDescriptor
    statement: RegistrationStorageStatement
    proof_commitment: str
    decoded_registrar_runtime_hash: str
    decoded_value: bytes
    returndata: bytes
    seal: str = field(repr=False)
    _capability: object = field(repr=False, compare=False)

    @property
    def digest(self) -> str:
        return hashlib.sha256(
            b"TAIKO_VERIFIED_REGISTRATION_MEMBERSHIP_V2\x00"
            + migration_transition_encode((
                self.descriptor,
                self.statement.digest,
                self.proof_commitment,
                self.decoded_registrar_runtime_hash,
                self.decoded_value,
                self.returndata,
            ))
        ).hexdigest()

    def __post_init__(self) -> None:
        if (self._capability is not _REGISTRATION_MPT_RESULT_CAPABILITY
                or type(self.descriptor)
                    is not RegistrationMptVerifierDescriptor
                or not self.descriptor.structurally_valid()
                or type(self.statement) is not RegistrationStorageStatement
                or not self.proof_commitment
                or self.decoded_registrar_runtime_hash
                    != self.statement.registrar_code_hash
                or self.decoded_value
                    != self.statement.expected_value
                or type(self.returndata) is not bytes
                or not self.seal):
            raise ValueError("verified registration membership is invalid")


class IRegistrationMptVerifier:
    @property
    def descriptor(self) -> RegistrationMptVerifierDescriptor:
        raise NotImplementedError

    def verify_membership(
        self,
        statement: RegistrationStorageStatement,
        proof: CanonicalMptMembershipProof,
    ) -> VerifiedRegistrationMembership:
        raise NotImplementedError

    def valid_result(self, result: VerifiedRegistrationMembership) -> bool:
        raise NotImplementedError


class TestRegistrationMptVerifier(IRegistrationMptVerifier):
    """Test-only stand-in for the pinned canonical RLP/HP MPT verifier."""

    def __init__(self, descriptor: RegistrationMptVerifierDescriptor):
        if (type(descriptor) is not RegistrationMptVerifierDescriptor
                or not descriptor.structurally_valid()):
            raise ValueError("test registration MPT descriptor is invalid")
        self._descriptor = descriptor
        self._secret = object()
        self.returndata_override: bytes | None = None
        self.calldata_override: bytes | None = None
        self.config_calldata_override: bytes | None = None
        self.config_returndata_override: bytes | None = None
        self.config_gas_limit = REGISTRATION_MPT_CONFIG_GETTER_GAS
        self.verification_gas_limit = REGISTRATION_MPT_VERIFIER_GAS_LIMIT
        self.raise_on_verify = False

    @property
    def descriptor(self) -> RegistrationMptVerifierDescriptor:
        return self._descriptor

    def _seal(self, namespace: bytes, digest: str) -> str:
        return hashlib.sha256(
            namespace
            + id(self._secret).to_bytes(32, "big")
            + digest.encode()
        ).hexdigest()

    @staticmethod
    def _proof_commitment(proof: CanonicalMptMembershipProof) -> str:
        return hashlib.sha256(
            b"TAIKO_CANONICAL_MPT_PROOF_V2\x00"
            + proof.canonical_bytes
        ).hexdigest()

    def verify_membership(
        self,
        statement: RegistrationStorageStatement,
        proof: CanonicalMptMembershipProof,
    ) -> VerifiedRegistrationMembership:
        descriptor = self.descriptor
        if self.raise_on_verify:
            raise RuntimeError("simulated registration verifier revert/OOG")
        config_calldata = (
            REGISTRATION_MPT_CONFIG_GETTER_SELECTOR
            if self.config_calldata_override is None
            else self.config_calldata_override
        )
        config_returndata = (
            bytes.fromhex(descriptor.configuration_hash)
            if self.config_returndata_override is None
            else self.config_returndata_override
        )
        if (config_calldata != REGISTRATION_MPT_CONFIG_GETTER_SELECTOR
                or self.config_gas_limit != REGISTRATION_MPT_CONFIG_GETTER_GAS
                or type(config_returndata) is not bytes
                or len(config_returndata) != REGISTRATION_MPT_CONFIG_GETTER_BYTES
                or config_returndata
                    != bytes.fromhex(descriptor.configuration_hash)
                or self.verification_gas_limit
                    != descriptor.verification_gas_limit):
            raise ValueError("registration verifier config surface is invalid")
        nodes = (
            proof.account_nodes + proof.storage_nodes
            if type(proof) is CanonicalMptMembershipProof else ()
        )
        try:
            expected_calldata = registration_verifier_calldata(
                statement, proof
            )
        except (AttributeError, TypeError, ValueError):
            raise ValueError("registration verifier calldata is noncanonical")
        actual_calldata = (
            expected_calldata if self.calldata_override is None
            else self.calldata_override
        )
        if (type(statement) is not RegistrationStorageStatement
                or type(proof) is not CanonicalMptMembershipProof
                or not proof.account_nodes or not proof.storage_nodes
                or len(proof.account_nodes) > descriptor.maximum_path_nodes
                or len(proof.storage_nodes) > descriptor.maximum_path_nodes
                or len(nodes) > descriptor.maximum_nodes
                or any(type(node) is not bytes
                       or not 0 < len(node) <= descriptor.maximum_node_bytes
                       for node in nodes)
                or sum(len(node) for node in nodes)
                    > descriptor.maximum_total_bytes
                or len(proof.canonical_bytes) > descriptor.maximum_total_bytes
                or actual_calldata != expected_calldata
                or actual_calldata[:4] != descriptor.selector):
            raise ValueError("registration MPT proof is malformed or unbounded")
        proof_commitment = self._proof_commitment(proof)
        proof_digest = hashlib.sha256(
            b"TAIKO_TEST_REGISTRATION_MPT_PROOF_V2\x00"
            + migration_transition_encode((
                descriptor,
                statement.digest,
                proof_commitment,
            ))
        ).hexdigest()
        if proof._test_seal != self._seal(
                b"TAIKO_TEST_REGISTRATION_MPT_PROOF_SEAL_V2\x00",
                proof_digest,
        ):
            raise ValueError("registration account/storage proof did not verify")
        result = VerifiedRegistrationMembership(
            self,
            descriptor,
            statement,
            proof_commitment,
            statement.registrar_code_hash,
            statement.expected_value,
            (
                bytes.fromhex(statement.digest)
                if self.returndata_override is None
                else self.returndata_override
            ),
            "PENDING",
            _REGISTRATION_MPT_RESULT_CAPABILITY,
        )
        return replace(
            result,
            seal=self._seal(
                b"TAIKO_REGISTRATION_MPT_RESULT_SEAL_V2\x00",
                result.digest,
            ),
        )

    def valid_result(self, result: VerifiedRegistrationMembership) -> bool:
        return (
            type(result) is VerifiedRegistrationMembership
            and result.verifier is self
            and result.descriptor == self.descriptor
            and result.seal == self._seal(
                b"TAIKO_REGISTRATION_MPT_RESULT_SEAL_V2\x00",
                result.digest,
            )
        )


def issue_registration_mpt_proof_for_test(
    verifier: TestRegistrationMptVerifier,
    statement: RegistrationStorageStatement,
    *,
    account_nodes: tuple[bytes, ...] = (b"canonical-account-node",),
    storage_nodes: tuple[bytes, ...] = (b"canonical-storage-node",),
) -> CanonicalMptMembershipProof:
    """Fixture-only issuance of raw nodes accepted by the test verifier."""

    if (type(verifier) is not TestRegistrationMptVerifier
            or type(statement) is not RegistrationStorageStatement):
        raise ValueError("test registration MPT proof inputs are invalid")
    proof = CanonicalMptMembershipProof(account_nodes, storage_nodes)
    proof_commitment = verifier._proof_commitment(proof)
    proof_digest = hashlib.sha256(
        b"TAIKO_TEST_REGISTRATION_MPT_PROOF_V2\x00"
        + migration_transition_encode((
            verifier.descriptor,
            statement.digest,
            proof_commitment,
        ))
    ).hexdigest()
    return replace(
        proof,
        _test_seal=verifier._seal(
            b"TAIKO_TEST_REGISTRATION_MPT_PROOF_SEAL_V2\x00",
            proof_digest,
        ),
    )


@dataclass(frozen=True)
class InboxApplyDeploymentDescriptor:
    """L1 commitment to InboxApply code/config, never a live L2 object."""

    address: str
    registrar_address: str
    runtime_hash: str
    configuration_hash: str

    def structurally_valid(self) -> bool:
        return (
            all((
                self.address,
                self.registrar_address,
                self.runtime_hash,
                self.configuration_hash,
            ))
            and self.runtime_hash == "code:inbox-apply"
            and self.configuration_hash
                == f"config:inbox-apply:{self.registrar_address}"
        )

    def authenticates(self, inbox: object) -> bool:
        """Compare only immutable deployment observations."""

        return (
            type(inbox) is InboxApplyRouterV2
            and self.structurally_valid()
            and inbox.address == self.address
            and inbox.registrar == self.registrar_address
            and inbox.runtime_hash == self.runtime_hash
            and inbox.configuration_hash == self.configuration_hash
        )


def inbox_apply_deployment_descriptor(
    inbox: "InboxApplyRouterV2",
) -> InboxApplyDeploymentDescriptor:
    if type(inbox) is not InboxApplyRouterV2:
        raise ValueError("InboxApply descriptor requires exact deployment")
    descriptor = InboxApplyDeploymentDescriptor(
        inbox.address,
        inbox.registrar,
        inbox.runtime_hash,
        inbox.configuration_hash,
    )
    if not descriptor.structurally_valid():
        raise ValueError("InboxApply descriptor is not canonical")
    return descriptor


def release_authority_descriptor_from_manifest(
    manifest: "ReleaseManifestV2",
) -> DestinationReleaseAuthorityDescriptor:
    if (type(manifest) is not ReleaseManifestV2
            or not manifest.structurally_valid()
            or len(manifest.components) != 10):
        raise ValueError("release authority descriptor has no exact manifest")
    authority_row = manifest.components[5]
    registrar_row = manifest.components[6]
    return DestinationReleaseAuthorityDescriptor(
        manifest.destination_chain_id,
        authority_row.address,
        authority_row.runtime_hash,
        authority_row.config_hash,
        registrar_row.address,
        registrar_row.runtime_hash,
        registrar_row.config_hash,
        REGISTRATION_SLOT_SCHEMA_HASH,
    )


@dataclass
class BridgeDomainRegistry:
    router: "ActiveSettlementRouter"
    manager: object
    release_authority_descriptor: DestinationReleaseAuthorityDescriptor
    registration_mpt_verifier: IRegistrationMptVerifier = field(
        compare=False, repr=False
    )
    entries: dict[tuple[str, str, str], BridgeSupportEntry] = field(default_factory=dict)
    profile_additions: dict[int, int] = field(default_factory=dict)
    _destinations_by_domain: dict[str, "ReleaseManifestV2"] = field(
        default_factory=dict, repr=False
    )
    _confirmed_at_by_domain: dict[str, int] = field(
        default_factory=dict, repr=False
    )
    _staged_registrations_by_version: dict[
        int, "SettlementRegistration"
    ] = field(default_factory=dict, repr=False)
    _key_by_destination_chain_version: dict[
        tuple[int, int], tuple[str, str, str]
    ] = field(default_factory=dict, repr=False)
    address: str = "bridge-domain-registry"
    runtime_hash: str = BRIDGE_DOMAIN_REGISTRY_RUNTIME_HASH
    configuration_hash: str = ""
    active_bridge_route_return_override: bytes | None = field(
        default=None, compare=False, repr=False
    )
    active_bridge_route_fault_point: str | None = field(
        default=None, compare=False, repr=False
    )
    bridge_route_package_return_override: bytes | None = field(
        default=None, compare=False, repr=False
    )
    bridge_route_package_fault_point: str | None = field(
        default=None, compare=False, repr=False
    )
    stage_bridge_route_return_override: bytes | None = field(
        default=None, compare=False, repr=False
    )
    stage_bridge_route_fault_point: str | None = field(
        default=None, compare=False, repr=False
    )
    consume_bridge_route_return_override: bytes | None = field(
        default=None, compare=False, repr=False
    )
    consume_bridge_route_fault_point: str | None = field(
        default=None, compare=False, repr=False
    )

    def __post_init__(self) -> None:
        expected = bridge_domain_registry_configuration_hash(
            address=self.address,
            runtime_hash=self.runtime_hash,
            support_authority=self.manager.address,
            router_address=self.router.address,
            router_runtime_hash=self.router.runtime_hash,
            router_configuration_hash=self.router.configuration_hash,
            release_authority_address=(
                self.release_authority_descriptor.authority_address
            ),
            release_authority_runtime_hash=(
                self.release_authority_descriptor.authority_runtime_hash
            ),
            release_authority_configuration_hash=(
                self.release_authority_descriptor
                    .authority_configuration_hash
            ),
            registration_mpt_verifier_descriptor_hash=(
                self.registration_mpt_verifier.descriptor.commitment
            ),
        )
        if (type(self.router) is not ActiveSettlementRouter
                or type(self.manager) not in {
                    ProtocolVersionManager, ProtocolVersionManagerV1
                }
                or self.manager.router is not self.router
                or self.router._version_manager_authority is not self.manager
                or type(self.release_authority_descriptor)
                    is not DestinationReleaseAuthorityDescriptor
                or not self.release_authority_descriptor.structurally_valid()
                or not isinstance(
                    self.registration_mpt_verifier,
                    IRegistrationMptVerifier,
                )
                or type(self.registration_mpt_verifier.descriptor)
                    is not RegistrationMptVerifierDescriptor
                or not self.registration_mpt_verifier.descriptor
                    .structurally_valid()
                or self.configuration_hash
                    not in {"", expected}):
            raise ValueError("Bridge support registry authority graph is invalid")
        object.__setattr__(self, "configuration_hash", expected)

    def __setattr__(self, name: str, value: object) -> None:
        if name in {
            "router", "manager", "release_authority_descriptor",
            "registration_mpt_verifier", "address", "runtime_hash",
            "configuration_hash",
        } and name in self.__dict__:
            raise AttributeError(f"Bridge support registry {name} is immutable")
        object.__setattr__(self, name, value)

    def _transaction_snapshot(self) -> dict[str, object]:
        return copy.deepcopy({
            key: value for key, value in self.__dict__.items()
            if key not in {
                "router", "manager", "release_authority_descriptor",
                "registration_mpt_verifier",
            }
        })

    def _restore_transaction_snapshot(
        self, snapshot: dict[str, object]
    ) -> None:
        router, manager, authority_descriptor, proof_verifier = (
            self.router, self.manager, self.release_authority_descriptor,
            self.registration_mpt_verifier,
        )
        self.__dict__.clear()
        self.__dict__.update(snapshot)
        object.__setattr__(self, "router", router)
        object.__setattr__(self, "manager", manager)
        object.__setattr__(
            self, "release_authority_descriptor", authority_descriptor
        )
        object.__setattr__(
            self, "registration_mpt_verifier", proof_verifier
        )

    @staticmethod
    def _package_root(
        registration: "SettlementRegistration",
        authorization: "ProfileIngressAuthorization",
    ) -> bytes:
        """Commit the exact one-route source package without live aliases."""

        return keccak256(b"".join((
            b"slot-chain-source-route-package-v1",
            _model_uint(registration.settlement.protocol_version, 8,
                        "route package protocol version"),
            _model_uint(authorization.source_chain_id, 8,
                        "route package source chain"),
            _model_uint(registration.release_manifest.destination_chain_id, 8,
                        "route package destination chain"),
            target_registration_hash_v2(registration),
            registration.release_manifest.commitment,
            authorization.authorization_id,
            authorization.source_descriptor_id,
            _model_address20(authorization.adapter_address),
            _model_fixed_bytes32(authorization.runtime_hash),
            _model_fixed_bytes32(authorization.configuration_hash),
            _model_address20(authorization.source_descriptor.source_bridge),
            _model_address20(
                authorization.source_descriptor.bridge_credit_registry
            ),
            _model_address20(
                authorization.source_descriptor.native_quota_manager
            ),
        )))

    @staticmethod
    def _primitive_package_root_v2(
        rtr_raw: bytes, brx_raw: bytes, pir_raw: bytes, pim_raw: bytes,
        pia_raw: bytes, bip_raw: bytes,
    ) -> bytes:
        """Commit the six exact raw authority rows read before first write."""

        expected_lengths = (
            TARGET_RELEASE_REGISTRATION_RETURN_LENGTH,
            BRIDGE_ROUTE_EXPANSION_RETURN_LENGTH,
            PROFILE_INGRESS_ROOT_RETURN_LENGTH,
            PROFILE_INGRESS_MEMBERSHIP_RETURN_LENGTH,
            PROFILE_INGRESS_AUTHORIZATION_RETURN_LENGTH,
            BRIDGE_INVOCATION_POLICY_RETURN_LENGTH,
        )
        rows = (rtr_raw, brx_raw, pir_raw, pim_raw, pia_raw, bip_raw)
        if any(type(raw) is not bytes or len(raw) != length
               for raw, length in zip(rows, expected_lengths)):
            raise ValueError("route package primitive width is invalid")
        return keccak256(b"".join((
            b"slot-chain-source-route-package-v2",
            *(keccak256(raw) for raw in rows),
        )))

    def _primitive_package_exact(self, entry: BridgeSupportEntry) -> bool:
        if type(entry) is not BridgeSupportEntry:
            return False
        hashes = (
            entry.rtr_hash, entry.brx_hash, entry.pir_hash, entry.pim_hash,
            entry.pia_hash, entry.bip_hash,
        )
        return (
            entry.manifest is None
            and entry.package_count == 1
            and all(value != bytes(32) for value in hashes)
            and entry.brx_hash == entry.bridge_route_expansion_hash
            and entry.package_root == keccak256(b"".join((
                b"slot-chain-source-route-package-v2", *hashes,
            )))
            and entry.source_domain_id != bytes(32)
            and entry.bridge_execution_hash != bytes(32)
            and entry.destination_domain_id != bytes(32)
            and entry.destination_bridge != bytes(20)
            and entry.target_settlement != bytes(20)
            and entry.release_manifest_hash != bytes(32)
            and entry.execution_profile_hash != bytes(32)
            and entry.invocation_policy_hash != bytes(32)
            and entry.bridge_authorization_id != bytes(32)
            and entry.source_bridge_address != bytes(20)
            and entry.source_credit_registry_address != bytes(20)
            and entry.source_quota_manager_address != bytes(20)
        )

    def _primitive_entry_matches_rows_v2(
        self, entry: BridgeSupportEntry, rtr: "TargetReleaseRegistrationRowV2",
        brx: BridgeRouteExpansionV1, pir_raw: bytes, pim_raw: bytes,
        pia_raw: bytes, bip: BridgeInvocationPolicyV1, bip_raw: bytes,
        rtr_raw: bytes, brx_raw: bytes,
    ) -> bool:
        """Pure full scalar/hash join shared by stage and consume."""

        try:
            pir_version, pir_count, pir_root = decode_profile_ingress_root_v2(
                pir_raw)
            pim_version, pim_id, pim_count, pim_root = (
                decode_profile_ingress_membership_v2(pim_raw))
            pia_id, pia = decode_profile_ingress_authorization_v2(pia_raw)
            descriptor = brx.source_descriptor_words
            version = entry.protocol_version
            return (
                rtr.protocol_version == brx.protocol_version == version
                and pir_version == pim_version == bip.protocol_version == version
                and pir_count == pim_count and pir_root == pim_root
                and pim_id == pia_id == brx.bridge_authorization_id
                and entry.target_settlement == rtr.target_settlement
                and entry.target_registration_hash
                    == rtr.target_registration_hash
                and entry.release_manifest_hash == rtr.release_manifest_hash
                and entry.execution_profile_hash == rtr.execution_profile_hash
                and entry.bridge_route_expansion_hash
                    == rtr.bridge_route_expansion_hash == keccak256(brx_raw)
                and entry.source_chain_id == brx.source_chain_id
                and entry.source_registration_epoch == _decode_uint_word_v1(
                    descriptor[27], 64, "route source epoch")
                and entry.source_domain_id == brx.source_domain_id == pia[10]
                and entry.bridge_execution_hash
                    == brx.source_bridge_execution_hash == pia[12]
                and entry.destination_chain_id
                    == _decode_uint_word_v1(pia[13], 256,
                                            "route destination chain")
                and entry.destination_domain_id == pia[14]
                and entry.destination_bridge == pia[15][12:]
                and entry.registration_commitment
                    == brx.destination_registration_commitment
                and entry.invocation_policy_hash
                    == brx.invocation_policy_hash
                    == bip.invocation_policy_hash
                and entry.bridge_authorization_id
                    == brx.bridge_authorization_id
                and entry.source_descriptor_id
                    == brx.source_bridge_execution_hash
                and _model_address20(entry.adapter_address) == pia[1][12:]
                and entry.adapter_runtime_hash == pia[2]
                and entry.adapter_configuration_hash == pia[3]
                and entry.source_bridge_address == descriptor[8][12:]
                and entry.source_credit_registry_address == descriptor[12][12:]
                and entry.source_quota_manager_address == descriptor[15][12:]
                and entry.rtr_hash == keccak256(rtr_raw)
                and entry.brx_hash == keccak256(brx_raw)
                and entry.pir_hash == keccak256(pir_raw)
                and entry.pim_hash == keccak256(pim_raw)
                and entry.pia_hash == keccak256(pia_raw)
                and entry.bip_hash == keccak256(bip_raw)
                and entry.package_root == self._primitive_package_root_v2(
                    rtr_raw, brx_raw, pir_raw, pim_raw, pia_raw, bip_raw)
                and self._primitive_package_exact(entry)
            )
        except (TypeError, ValueError):
            return False

    def _primitive_entry_live_exact_v2(
        self, entry: BridgeSupportEntry,
    ) -> bool:
        """Re-read every primitive row and the exact prepared live package."""

        manager = self.manager
        router = self.router
        version = entry.protocol_version
        try:
            rtr_raw = router.staticcall_target_release_registration_v2(
                TARGET_RELEASE_REGISTRATION_SELECTOR
                + _model_uint(version, 32, "route RTR2 version"),
                caller=self.address, value=0,
                gas=TARGET_RELEASE_REGISTRATION_READ_GAS,
            )
            rtr = decode_target_release_registration_return_v2(rtr_raw)
            brx_raw = router.staticcall_bridge_route_expansion_v1(
                BRIDGE_ROUTE_EXPANSION_SELECTOR
                + _model_uint(version, 32, "route BRX1 version"),
                caller=self.address, value=0,
                gas=BRIDGE_ROUTE_EXPANSION_READ_GAS,
            )
            brx = decode_bridge_route_expansion_v1(brx_raw)
            pir_raw = manager.staticcall_profile_ingress_root_v2(
                PROFILE_INGRESS_ROOT_SELECTOR
                + _model_uint(version, 32, "route PIR2 version"),
                caller=self.address, value=0,
                gas=PROFILE_INGRESS_ROOT_READ_GAS,
            )
            pim_raw = manager.staticcall_profile_ingress_membership_v2(
                PROFILE_INGRESS_MEMBERSHIP_SELECTOR
                + _model_uint(version, 32, "route PIM2 version")
                + brx.bridge_authorization_id,
                caller=self.address, value=0,
                gas=PROFILE_INGRESS_MEMBERSHIP_READ_GAS,
            )
            pia_raw = manager.staticcall_profile_ingress_authorization_v2(
                PROFILE_INGRESS_AUTHORIZATION_SELECTOR
                + brx.bridge_authorization_id,
                caller=self.address, value=0,
                gas=PROFILE_INGRESS_AUTHORIZATION_READ_GAS,
            )
            _pia_id, pia = decode_profile_ingress_authorization_v2(pia_raw)
            bip_raw = router.staticcall_bridge_invocation_policy_v1(
                BRIDGE_INVOCATION_POLICY_SELECTOR
                + _model_uint(version, 32, "route BIP1 version"),
                caller=self.address, value=0,
                gas=BRIDGE_INVOCATION_POLICY_READ_GAS,
            )
            bip = decode_bridge_invocation_policy_v1(bip_raw)
            if not self._primitive_entry_matches_rows_v2(
                    entry, rtr, brx, pir_raw, pim_raw, pia_raw, bip, bip_raw,
                    rtr_raw, brx_raw):
                return False
            descriptor = brx.source_descriptor_words
            factory = router._source_bridge_factories_by_address.get(
                "0x" + descriptor[0][12:].hex())
            deployment = router._profile_deployments_by_version.get(
                version, {}).get(brx.bridge_authorization_id)
            bundle = router._source_bundles_by_descriptor_id.get(
                brx.source_bridge_execution_hash)
            expected_adapter = bridge_adapter_create2_address_v1(
                factory="0x" + descriptor[0][12:].hex(),
                protocol_version=version,
                source_descriptor_id=brx.source_bridge_execution_hash,
                configuration_hash=pia[3],
                source_bridge="0x" + descriptor[8][12:].hex(),
                credit_registry="0x" + descriptor[12][12:].hex(),
                router=router.address, queue=router.forced_queue.address,
                seal_authority=router.version_manager,
            )
            return (
                type(factory) is ImmutableV2BridgeFactory
                and _model_fixed_bytes32(factory.runtime_hash)
                    == descriptor[1]
                and _model_fixed_bytes32(factory.configuration_hash)
                    == descriptor[2]
                and type(deployment) is BridgeAdapter
                and bundle is not None and len(bundle) == 3
                and deployment is factory._adapters.get(expected_adapter)
                and deployment.source_bridge is bundle[0]
                and deployment.credit_registry is bundle[1]
                and bundle[0].quota_manager is bundle[2]
                and _model_address20(deployment.address) == pia[1][12:]
                and _model_fixed_bytes32(deployment.runtime_hash) == pia[2]
                and _model_fixed_bytes32(deployment.configuration_hash)
                    == pia[3]
                and _model_address20(deployment.queue_address) == pia[7][12:]
            )
        except (AttributeError, TypeError, ValueError, RuntimeError):
            return False

    def _package_exact(self, entry: BridgeSupportEntry) -> bool:
        registration = self.router.registrations.get(entry.protocol_version)
        # A registered target is not yet in Router.registrations.  Its exact
        # package is nevertheless retained in the version-indexed deployment
        # journal and is rejoined to the registration supplied by the caller.
        if registration is None:
            registration = self._staged_registrations_by_version.get(
                entry.protocol_version
            )
        authorization = (
            None if type(registration) is not SettlementRegistration
            else registration.ingress_authorizations_by_address.get(
                entry.adapter_address
            )
        )
        deployment = (
            None if type(authorization) is not ProfileIngressAuthorization
            else self.router._profile_deployments_by_version.get(
                entry.protocol_version, {}
            ).get(authorization.authorization_id)
        )
        descriptor_id = self.router._source_descriptor_id_by_version.get(
            entry.protocol_version
        )
        bundle = self.router._source_bundles_by_descriptor_id.get(descriptor_id)
        return (
            type(registration) is SettlementRegistration
            and type(authorization) is ProfileIngressAuthorization
            and authorization.kind is ForceKind.BRIDGE_CREDIT
            and type(deployment) is BridgeAdapter
            and bundle is not None and len(bundle) == 3
            and deployment.source_bridge is bundle[0]
            and deployment.credit_registry is bundle[1]
            and bundle[0].quota_manager is bundle[2]
            and authorization.source_descriptor_id == descriptor_id
            and entry.target_registration_hash
                == target_registration_hash_v2(registration)
            and entry.source_descriptor_id == descriptor_id
            and entry.adapter_address == authorization.adapter_address
            and entry.package_count == 1
            and entry.package_root
                == self._package_root(registration, authorization)
        )

    def stage(self, source_domain_id: str, execution_hash: str,
              manifest: "ReleaseManifestV2", *,
              manager: object, clock: Clock,
              registration: "SettlementRegistration | None" = None) -> bool:
        registration = (
            self.router.registrations.get(
                getattr(manifest, "protocol_version", 0)
            ) if registration is None else registration
        )
        authorization = (
            None if registration is None or len(manifest.components) != 10
            else registration.ingress_authorizations_by_address.get(
                manifest.components[0].address
            )
        )
        source_descriptor = (
            None if type(authorization) is not ProfileIngressAuthorization
            else authorization.source_descriptor
        )
        if (manager is not self.manager or type(clock) is not Clock
                or type(manifest) is not ReleaseManifestV2
                or type(registration) is not SettlementRegistration
                or registration.settlement.protocol_version
                    != manifest.protocol_version
                or not manifest.structurally_valid()
                or manifest.execution_profile_hash
                    != registration.execution_profile_hash
                or registration.execution_profile
                    is not registration.settlement.execution_profile
                or manifest.migration_transition_verifier
                    != registration.execution_profile
                        .migration_transition_verifier_descriptor
                or manifest is not registration.release_manifest
                or registration.release_manifests_by_adapter.get(
                    manifest.components[0].address
                ) is not manifest
                or registration.release_manifest_hash != manifest.commitment
                or registration.settlement_chain_context_id
                    != self.router.settlement_chain_context_id
                or manifest.settlement_chain_id
                    != self.router.settlement_chain_context_id
                or manifest.ingress_authorization_root
                    != registration.ingress_authorization_root
                or type(authorization) is not ProfileIngressAuthorization
                or authorization.kind is not ForceKind.BRIDGE_CREDIT
                or source_descriptor.descriptor_id
                    != authorization.source_descriptor_id
                or source_descriptor.settlement_chain_id
                    != registration.settlement.market_settlement_chain_id
                or source_descriptor.settlement_chain_id
                    != self.router.settlement_chain_context_id
                or source_descriptor.source_domain_id
                    != authorization.source_domain_id
                or source_descriptor.bridge_execution_hash
                    != authorization.frozen_bridge_execution_hash
                or _model_fixed_bytes32(source_descriptor
                    .source_terminal_verifier_configuration_hash)
                    != _model_fixed_bytes32(manifest.components[2].config_hash)
                or source_domain_id != authorization.source_domain_id
                or execution_hash
                    != authorization.frozen_bridge_execution_hash
                or not 0 < authorization.source_chain_id <= UINT64_MAX
                or not 0 < authorization.source_registration_epoch
                    <= UINT64_MAX
                or _model_fixed_bytes32(authorization.runtime_hash)
                    != _model_fixed_bytes32(manifest.components[0].runtime_hash)
                or _model_fixed_bytes32(authorization.configuration_hash)
                    != _model_fixed_bytes32(manifest.components[0].config_hash)
                or authorization.destination_domain_id
                    != manifest.destination_domain_id
                or authorization.destination_bridge
                    != manifest.destination_bridge
                or authorization.destination_descriptor_id
                    != manifest.canonical_destination_descriptor.descriptor_id):
            return False
        key = (
            source_domain_id,
            execution_hash,
            manifest.destination_domain_id,
        )
        version_key = (
            manifest.destination_chain_id, manifest.protocol_version
        )
        derived = derive_register_release_authority_v2(
            registration.execution_profile.canonical_profile_bytes,
            registration.predecessor_version,
        )
        # Genesis fixtures predate REGISTER_RELEASE.  Root deployment installs
        # an equally exact RTR2 row for the already-live Settlement address;
        # successors never use this compatibility derivation.
        genesis_rtr = replace(
            derived.target_registration_row,
            target_settlement=_model_address20(registration.settlement.address),
            target_registration_hash=target_registration_hash_v2(registration),
        )
        rtr_raw = encode_target_release_registration_return_v2(
            genesis_rtr)
        brx_raw = derived.bridge_route_expansion
        bip_raw = derived.bridge_invocation_policy
        ids = derived.ingress_ids
        pir_raw = b"".join((
            b"PIR2" + bytes(28),
            _model_uint(manifest.protocol_version, 32, "PIR2 version"),
            _model_uint(len(ids), 32, "PIR2 count"),
            derived.ingress_authorization_root,
        ))
        pim_raw = b"".join((
            PROFILE_INGRESS_MEMBERSHIP_MAGIC + bytes(28),
            _model_uint(manifest.protocol_version, 32, "PIM2 version"),
            authorization.authorization_id,
            _model_uint(len(ids), 32, "PIM2 count"),
            derived.ingress_authorization_root,
        ))
        pia_raw = (b"PIA2" + bytes(28) + authorization.authorization_id
                   + profile_ingress_authorization_abi_v2(authorization))
        bip = decode_bridge_invocation_policy_v1(bip_raw)
        existing_rtr = self.router.target_release_registrations_v2.get(
            manifest.protocol_version)
        if (existing_rtr is not None
                and existing_rtr != genesis_rtr):
            return False
        self.router.target_release_registrations_v2.setdefault(
            manifest.protocol_version, genesis_rtr)
        self.router.bridge_route_expansions_v1.setdefault(
            manifest.protocol_version, brx_raw)
        self.router.bridge_invocation_policies_v1.setdefault(
            manifest.protocol_version, bip_raw)
        entry = BridgeSupportEntry(
            protocol_version=manifest.protocol_version, manifest=None,
            registration_commitment=manifest.registration_commitment,
            source_chain_id=authorization.source_chain_id,
            source_registration_epoch=authorization.source_registration_epoch,
            staged_at_block=clock.block_number,
            target_registration_hash=genesis_rtr.target_registration_hash,
            source_descriptor_id=authorization.source_descriptor_id,
            adapter_address=authorization.adapter_address,
            # Compatibility rows retain the original one-route commitment.
            # The six-raw-row root is reserved for BRS1 PRIMITIVE rows; using
            # it here would make the LEGACY arm-ready verifier permanently
            # reject this entry.
            package_root=self._package_root(registration, authorization),
            package_count=1,
            destination_chain_id=manifest.destination_chain_id,
            source_domain_id=_model_fixed_bytes32(
                authorization.source_domain_id),
            bridge_execution_hash=_model_fixed_bytes32(
                authorization.frozen_bridge_execution_hash),
            destination_domain_id=_model_fixed_bytes32(
                authorization.destination_domain_id),
            destination_bridge=_model_address20(
                authorization.destination_bridge),
            target_settlement=_model_address20(registration.settlement.address),
            release_manifest_hash=manifest.commitment,
            execution_profile_hash=_model_fixed_bytes32(
                registration.execution_profile_hash),
            invocation_policy_hash=bip.invocation_policy_hash,
            bridge_authorization_id=authorization.authorization_id,
            bridge_route_expansion_hash=keccak256(brx_raw),
            adapter_runtime_hash=_model_fixed_bytes32(authorization.runtime_hash),
            adapter_configuration_hash=_model_fixed_bytes32(
                authorization.configuration_hash),
            source_bridge_address=_model_address20(
                authorization.source_descriptor.source_bridge),
            source_credit_registry_address=_model_address20(
                authorization.source_descriptor.bridge_credit_registry),
            source_quota_manager_address=_model_address20(
                authorization.source_descriptor.native_quota_manager),
            rtr_hash=keccak256(rtr_raw), brx_hash=keccak256(brx_raw),
            pir_hash=keccak256(pir_raw), pim_hash=keccak256(pim_raw),
            pia_hash=keccak256(pia_raw), bip_hash=keccak256(bip_raw),
            route_kind="LEGACY",
        )
        if key in self.entries:
            existing = self.entries[key]
            exact = (
                existing.protocol_version == manifest.protocol_version
                and existing.registration_commitment
                    == manifest.registration_commitment
                and existing.source_chain_id == entry.source_chain_id
                and existing.source_registration_epoch
                    == entry.source_registration_epoch
                and existing.destination_bridge
                    == _model_address20(manifest.destination_bridge)
                and existing.destination_domain_id
                    == _model_fixed_bytes32(manifest.destination_domain_id)
                and existing.target_registration_hash
                    == entry.target_registration_hash
                and existing.source_descriptor_id == entry.source_descriptor_id
                and existing.adapter_address == entry.adapter_address
                and existing.package_root == entry.package_root
                and existing.package_count == entry.package_count
                and self._key_by_destination_chain_version.get(version_key)
                    == key
                and existing.route_kind == "LEGACY"
                and self._package_exact(existing)
            )
            return exact
        existing_manifest = self._destinations_by_domain.get(
            manifest.destination_domain_id
        )
        if (existing_manifest is not None
                and (existing_manifest.destination_bridge
                    != manifest.destination_bridge
                     or existing_manifest.canonical_destination_descriptor
                    != manifest.canonical_destination_descriptor
                     or existing_manifest.components != manifest.components)):
            return False
        if self.profile_additions.get(manifest.protocol_version, 0) \
                >= MAX_BRIDGE_TOPOLOGIES_PER_PROFILE:
            return False
        if version_key in self._key_by_destination_chain_version:
            return False
        self.entries[key] = entry
        self._staged_registrations_by_version[
            manifest.protocol_version
        ] = registration
        self._destinations_by_domain.setdefault(
            manifest.destination_domain_id, manifest
        )
        self.profile_additions[manifest.protocol_version] = (
            self.profile_additions.get(manifest.protocol_version, 0) + 1)
        self._key_by_destination_chain_version[version_key] = key
        return True

    def stage_bridge_route_package_v1(
        self,
        calldata: bytes,
        *,
        caller: str,
        value: int,
        gas: int,
        clock: Clock,
    ) -> bytes:
        """Stage one package solely from exact Router/PVM primitive reads."""

        if self.stage_bridge_route_fault_point in {"revert", "oog"}:
            raise RuntimeError("injected BRS1 call fault")
        if (type(calldata) is not bytes or len(calldata) != 36
                or calldata[:4] != STAGE_BRIDGE_ROUTE_PACKAGE_SELECTOR
                or calldata[4:28] != bytes(24)
                or caller != self.router.address or value != 0
                or gas != STAGE_BRIDGE_ROUTE_PACKAGE_GAS
                or type(clock) is not Clock
                or self.router.migration_lifecycle
                    is not RouterMigrationLifecycle.BRIDGE_PREPARING):
            raise ValueError("BRS1 call envelope is noncanonical")
        version = int.from_bytes(calldata[28:36], "big")
        if type(self.manager) is not ProtocolVersionManagerV1 or version == 0:
            raise ValueError("BRS1 requires the strict production PVM")

        # Normative read order.  No persistent write occurs until all exact
        # raw rows, every cross-row join and the live adapter observation pass.
        mact_raw = self.router.staticcall_migration_activation_context_v1(
            MIGRATION_ACTIVATION_CONTEXT_SELECTOR,
            caller=self.address, value=0, gas=MIGRATION_ACTIVATION_CONTEXT_GAS,
        )
        mact = decode_migration_activation_context_v1(mact_raw)
        rtr_raw = self.router.staticcall_target_release_registration_v2(
            TARGET_RELEASE_REGISTRATION_SELECTOR
            + _model_uint(version, 32, "RTR2 protocol version"),
            caller=self.address, value=0,
            gas=TARGET_RELEASE_REGISTRATION_READ_GAS,
        )
        rtr = decode_target_release_registration_return_v2(rtr_raw)
        brx_raw = self.router.staticcall_bridge_route_expansion_v1(
            BRIDGE_ROUTE_EXPANSION_SELECTOR
            + _model_uint(version, 32, "BRX1 protocol version"),
            caller=self.address, value=0, gas=BRIDGE_ROUTE_EXPANSION_READ_GAS,
        )
        brx = decode_bridge_route_expansion_v1(brx_raw)
        pir_raw = self.manager.staticcall_profile_ingress_root_v2(
            PROFILE_INGRESS_ROOT_SELECTOR
            + _model_uint(version, 32, "PIR2 protocol version"),
            caller=self.address, value=0, gas=PROFILE_INGRESS_ROOT_READ_GAS,
        )
        pir_version, pir_count, pir_root = decode_profile_ingress_root_v2(
            pir_raw)
        pim_raw = self.manager.staticcall_profile_ingress_membership_v2(
            PROFILE_INGRESS_MEMBERSHIP_SELECTOR
            + _model_uint(version, 32, "PIM2 protocol version")
            + brx.bridge_authorization_id,
            caller=self.address, value=0,
            gas=PROFILE_INGRESS_MEMBERSHIP_READ_GAS,
        )
        pim_version, pim_id, pim_count, pim_root = (
            decode_profile_ingress_membership_v2(pim_raw))
        pia_raw = self.manager.staticcall_profile_ingress_authorization_v2(
            PROFILE_INGRESS_AUTHORIZATION_SELECTOR
            + brx.bridge_authorization_id,
            caller=self.address, value=0,
            gas=PROFILE_INGRESS_AUTHORIZATION_READ_GAS,
        )
        pia_id, pia = decode_profile_ingress_authorization_v2(pia_raw)
        bip_raw = self.router.staticcall_bridge_invocation_policy_v1(
            BRIDGE_INVOCATION_POLICY_SELECTOR
            + _model_uint(version, 32, "BIP1 protocol version"),
            caller=self.address, value=0,
            gas=BRIDGE_INVOCATION_POLICY_READ_GAS,
        )
        bip = decode_bridge_invocation_policy_v1(bip_raw)

        descriptor = brx.source_descriptor_words
        adapter_address = pia[1][12:]
        factory = self.router._source_bridge_factories_by_address.get(
            "0x" + descriptor[0][12:].hex())
        expected_adapter_address = bridge_adapter_create2_address_v1(
            factory="0x" + descriptor[0][12:].hex(),
            protocol_version=version,
            source_descriptor_id=brx.source_bridge_execution_hash,
            configuration_hash=pia[3],
            source_bridge="0x" + descriptor[8][12:].hex(),
            credit_registry="0x" + descriptor[12][12:].hex(),
            router=self.router.address, queue=self.router.forced_queue.address,
            seal_authority=self.router.version_manager,
        )
        deployment = self.router._profile_deployments_by_version.get(
            version, {}).get(brx.bridge_authorization_id)
        live_adapter_exact = (
            type(factory) is ImmutableV2BridgeFactory
            and _model_fixed_bytes32(factory.runtime_hash) == descriptor[1]
            and _model_fixed_bytes32(factory.configuration_hash)
                == descriptor[2]
            and type(deployment) is BridgeAdapter
            and _model_address20(deployment.address) == adapter_address
            and _model_address20(expected_adapter_address) == adapter_address
            and factory._adapters.get(expected_adapter_address) is deployment
            and _model_fixed_bytes32(deployment.runtime_hash) == pia[2]
            and _model_fixed_bytes32(deployment.configuration_hash) == pia[3]
            and _model_address20(deployment.queue_address) == pia[7][12:]
        )
        expected_registration_commitment = keccak256(b"".join((
            D_DESTINATION_REGISTRATION,
            _model_uint(version, 8, "registration version"),
            rtr.release_manifest_hash,
            _model_uint(
                _decode_uint_word_v1(pia[13], 256, "PIA2 destination"),
                32, "registration destination chain"),
            brx.destination_namespace, pia[14], pia[15][12:], pia[17],
            rtr.execution_profile_hash,
        )))
        if (mact.lifecycle is not RouterMigrationLifecycle.BRIDGE_PREPARING
                or rtr.protocol_version != version
                or brx.protocol_version != version
                or pir_version != version or pim_version != version
                or bip.protocol_version != version
                or rtr.bridge_route_expansion_hash != keccak256(brx_raw)
                or pir_count != pim_count or pir_root != pim_root
                or pim_id != brx.bridge_authorization_id
                or pia_id != brx.bridge_authorization_id
                or _decode_uint_word_v1(pia[0], 8, "PIA2 bridge kind")
                    != ForceKind.BRIDGE_CREDIT.value
                or pia[4][12:] != _model_address20(self.router.address)
                or pia[5] != _model_fixed_bytes32(self.router.runtime_hash)
                or pia[6]
                    != _model_fixed_bytes32(self.router.configuration_hash)
                or pia[7][12:]
                    != _model_address20(self.router.forced_queue.address)
                or pia[8]
                    != _model_fixed_bytes32(self.router.forced_queue.runtime_hash)
                or pia[9]
                    != _model_fixed_bytes32(self.router.forced_queue.config_hash)
                or pia[10] != brx.source_domain_id
                or _decode_uint_word_v1(pia[11], 64, "PIA2 source epoch")
                    != _decode_uint_word_v1(
                        descriptor[27], 64, "BRX1 source epoch")
                or pia[12] != brx.source_bridge_execution_hash
                or _decode_uint_word_v1(pia[13], 256, "PIA2 destination")
                    != self.release_authority_descriptor.destination_chain_id
                or pia[14] == bytes(32) or pia[15][12:] == bytes(20)
                or brx.invocation_policy_hash != bip.invocation_policy_hash
                or brx.invocation_policy_count != len(bip.denied)
                or brx.destination_registration_commitment
                    in {bytes(32), rtr.target_registration_hash}
                or brx.destination_registration_commitment
                    != expected_registration_commitment
                or descriptor[18][12:] != _model_address20(self.address)
                or descriptor[19] != _model_fixed_bytes32(self.runtime_hash)
                or descriptor[20]
                    != _model_fixed_bytes32(self.configuration_hash)
                or not live_adapter_exact):
            raise ValueError("BRS1 primitive authority join is inexact")
        package_root = self._primitive_package_root_v2(
            rtr_raw, brx_raw, pir_raw, pim_raw, pia_raw, bip_raw)
        key = (brx.source_domain_id.hex(),
               brx.source_bridge_execution_hash.hex(), pia[14].hex())
        version_key = (
            self.release_authority_descriptor.destination_chain_id, version)
        candidate = BridgeSupportEntry(
            protocol_version=version, manifest=None,
            registration_commitment=(
                brx.destination_registration_commitment),
            source_chain_id=brx.source_chain_id,
            source_registration_epoch=_decode_uint_word_v1(
                descriptor[27], 64, "BRX1 source epoch"),
            staged_at_block=clock.block_number,
            target_registration_hash=rtr.target_registration_hash,
            source_descriptor_id=brx.source_bridge_execution_hash,
            adapter_address="0x" + adapter_address.hex(),
            package_root=package_root, package_count=1,
            destination_chain_id=version_key[0],
            source_domain_id=brx.source_domain_id,
            bridge_execution_hash=brx.source_bridge_execution_hash,
            destination_domain_id=pia[14], destination_bridge=pia[15][12:],
            target_settlement=rtr.target_settlement,
            release_manifest_hash=rtr.release_manifest_hash,
            execution_profile_hash=rtr.execution_profile_hash,
            invocation_policy_hash=bip.invocation_policy_hash,
            bridge_authorization_id=brx.bridge_authorization_id,
            bridge_route_expansion_hash=rtr.bridge_route_expansion_hash,
            adapter_runtime_hash=pia[2], adapter_configuration_hash=pia[3],
            source_bridge_address=descriptor[8][12:],
            source_credit_registry_address=descriptor[12][12:],
            source_quota_manager_address=descriptor[15][12:],
            rtr_hash=keccak256(rtr_raw), brx_hash=keccak256(brx_raw),
            pir_hash=keccak256(pir_raw), pim_hash=keccak256(pim_raw),
            pia_hash=keccak256(pia_raw), bip_hash=keccak256(bip_raw),
        )
        if not self._primitive_entry_matches_rows_v2(
                candidate, rtr, brx, pir_raw, pim_raw, pia_raw, bip, bip_raw,
                rtr_raw, brx_raw):
            raise ValueError("BRS1 candidate primitive row is inexact")
        existing = self.entries.get(key)
        if existing is not None:
            # Idempotence never refreshes the review clock.
            if replace(candidate, staged_at_block=existing.staged_at_block) \
                    != existing:
                raise ValueError("BRS1 existing primitive row is polluted")
            entry = existing
        else:
            if (version_key in self._key_by_destination_chain_version
                    or self.profile_additions.get(version, 0)
                        >= MAX_BRIDGE_TOPOLOGIES_PER_PROFILE):
                raise ValueError("BRS1 route key is already occupied")
            self.entries[key] = candidate
            self._key_by_destination_chain_version[version_key] = key
            self.profile_additions[version] = (
                self.profile_additions.get(version, 0) + 1)
            entry = candidate
        result = b"".join((
            b"BRS1" + bytes(28),
            _model_uint(version, 32, "BRS1 version"),
            entry.package_root,
            _model_uint(
                entry.staged_at_block + BRIDGE_ROUTE_ARM_REVIEW_BLOCKS,
                32, "BRS1 ready block",
            ),
        ))
        if len(result) != STAGE_BRIDGE_ROUTE_PACKAGE_RETURN_LENGTH:
            raise AssertionError("BRS1 return width drifted")
        return (
            result if self.stage_bridge_route_return_override is None
            else self.stage_bridge_route_return_override
        )

    def arm_ready_entry(
        self,
        registration: "SettlementRegistration",
        destination_chain_id: int,
        clock: Clock,
    ) -> BridgeSupportEntry | None:
        """Exact-read one staged package after its L1 review delay."""

        key = self._key_by_destination_chain_version.get((
            destination_chain_id,
            getattr(getattr(registration, "settlement", None),
                    "protocol_version", 0),
        ))
        entry = self.entries.get(key) if key is not None else None
        package_exact = (
            False if entry is None
            else (
                self._primitive_entry_live_exact_v2(entry)
                if entry.route_kind == "PRIMITIVE"
                else self._package_exact(entry)
                    if entry.route_kind == "LEGACY" else False
            )
        )
        if (type(registration) is not SettlementRegistration
                or type(clock) is not Clock or entry is None
                or entry.protocol_version
                    != registration.settlement.protocol_version
                or entry.release_manifest_hash
                    != registration.release_manifest.commitment
                or entry.target_registration_hash
                    != target_registration_hash_v2(registration)
                or entry.arm_ready_consumed
                or clock.block_number < entry.staged_at_block
                    + BRIDGE_ROUTE_ARM_REVIEW_BLOCKS
                or not package_exact):
            return None
        return entry

    def _bridge_route_package_view_v1(
        self,
        destination_chain_id: int,
        protocol_version: int,
        clock: Clock,
    ) -> bytes:
        """Exact 15-word public package view used by arm conformance tests."""

        key = self._key_by_destination_chain_version.get((
            destination_chain_id, protocol_version
        ))
        entry = self.entries.get(key) if key is not None else None
        package_exact = (
            False if entry is None
            else self._primitive_package_exact(entry)
                if entry.route_kind == "PRIMITIVE"
            else self._package_exact(entry)
                if entry.route_kind == "LEGACY"
            else False
        )
        if (type(clock) is not Clock or entry is None or not package_exact):
            raise ValueError("unknown or polluted Bridge route package")
        state = (
            3 if entry.arm_ready_consumed
            else (2 if clock.block_number >= entry.staged_at_block
                    + BRIDGE_ROUTE_ARM_REVIEW_BLOCKS else 1)
        )
        ready_at = entry.staged_at_block + BRIDGE_ROUTE_ARM_REVIEW_BLOCKS
        encoded = b"".join((
            BRIDGE_ROUTE_PACKAGE_MAGIC + bytes(28),
            _model_uint(state, 32, "BRP1 state"),
            _model_uint(destination_chain_id, 32, "BRP1 destination chain"),
            _model_uint(protocol_version, 32, "BRP1 protocol version"),
            _model_uint(entry.staged_at_block, 32, "BRP1 staged block"),
            _model_uint(ready_at, 32, "BRP1 ready block"),
            entry.target_registration_hash,
            entry.source_descriptor_id,
            entry.bridge_authorization_id,
            entry.package_root,
            _model_uint(entry.package_count, 32, "BRP1 package count"),
            bytes(12) + entry.source_bridge_address,
            bytes(12) + entry.source_credit_registry_address,
            bytes(12) + entry.source_quota_manager_address,
            bytes(12) + _model_address20(entry.adapter_address),
        ))
        if len(encoded) != BRIDGE_ROUTE_PACKAGE_RETURN_LENGTH:
            raise AssertionError("BRP1 return width drifted")
        return encoded

    def bridge_route_package_v1(
        self,
        calldata: bytes,
        *,
        caller: str,
        value: int,
        gas: int,
        clock: Clock,
    ) -> bytes:
        """Executable, caller-independent BRP1 exact static-read boundary."""

        _ = caller
        if self.bridge_route_package_fault_point in {"revert", "oog"}:
            raise RuntimeError("injected BRP1 staticcall fault")
        if (type(calldata) is not bytes
                or len(calldata) != BRIDGE_ROUTE_PACKAGE_CALLDATA_LENGTH
                or calldata[:4] != BRIDGE_ROUTE_PACKAGE_SELECTOR
                or value != 0 or gas != BRIDGE_ROUTE_PACKAGE_READ_GAS
                or calldata[36:60] != bytes(24)):
            raise ValueError("BRP1 call envelope is noncanonical")
        destination_chain_id = int.from_bytes(calldata[4:36], "big")
        protocol_version = int.from_bytes(calldata[60:68], "big")
        if destination_chain_id == 0 or protocol_version == 0:
            raise ValueError("BRP1 lookup key is zero")
        result = self._bridge_route_package_view_v1(
            destination_chain_id, protocol_version, clock
        )
        return (
            result if self.bridge_route_package_return_override is None
            else self.bridge_route_package_return_override
        )

    def consume_bridge_route_arm_ready_v1(
        self,
        calldata: bytes,
        *,
        caller: str,
        value: int,
        gas: int,
        clock: Clock,
    ) -> bytes:
        """Executable BRC1 boundary authorized by MACT, ASR1, then RTR2."""

        if self.consume_bridge_route_fault_point in {"revert", "oog"}:
            raise RuntimeError("injected BRC1 call fault")
        if (type(calldata) is not bytes or len(calldata) != 68
                or calldata[:4] != CONSUME_BRIDGE_ROUTE_ARM_READY_SELECTOR
                or calldata[4:28] != bytes(24)
                or caller != self.router.address or value != 0
                or gas != CONSUME_BRIDGE_ROUTE_ARM_READY_GAS
                or type(clock) is not Clock):
            raise ValueError("BRC1 call envelope is noncanonical")
        version = int.from_bytes(calldata[28:36], "big")
        target_registration_hash = calldata[36:68]
        mact = decode_migration_activation_context_v1(
            self.router.staticcall_migration_activation_context_v1(
                MIGRATION_ACTIVATION_CONTEXT_SELECTOR,
                caller=self.address, value=0,
                gas=MIGRATION_ACTIVATION_CONTEXT_GAS,
            )
        )
        active = decode_active_settlement_state_v1(
            self.router.staticcall_active_settlement_state_v1(
                ACTIVE_SETTLEMENT_STATE_SELECTOR,
                caller=self.address, value=0,
                gas=ACTIVE_SETTLEMENT_STATE_GAS,
            )
        )
        row = decode_target_release_registration_return_v2(
            self.router.staticcall_target_release_registration_v2(
                TARGET_RELEASE_REGISTRATION_SELECTOR
                + _model_uint(version, 32, "RTR2 protocol version"),
                caller=self.address, value=0,
                gas=TARGET_RELEASE_REGISTRATION_READ_GAS,
            )
        )
        brx_raw = self.router.staticcall_bridge_route_expansion_v1(
            BRIDGE_ROUTE_EXPANSION_SELECTOR
            + _model_uint(version, 32, "BRC1 BRX1 version"),
            caller=self.address, value=0, gas=BRIDGE_ROUTE_EXPANSION_READ_GAS,
        )
        brx = decode_bridge_route_expansion_v1(brx_raw)
        pir_raw = self.manager.staticcall_profile_ingress_root_v2(
            PROFILE_INGRESS_ROOT_SELECTOR
            + _model_uint(version, 32, "BRC1 PIR2 version"),
            caller=self.address, value=0, gas=PROFILE_INGRESS_ROOT_READ_GAS,
        )
        pir_version, pir_count, pir_root = decode_profile_ingress_root_v2(
            pir_raw)
        pim_raw = self.manager.staticcall_profile_ingress_membership_v2(
            PROFILE_INGRESS_MEMBERSHIP_SELECTOR
            + _model_uint(version, 32, "BRC1 PIM2 version")
            + brx.bridge_authorization_id,
            caller=self.address, value=0,
            gas=PROFILE_INGRESS_MEMBERSHIP_READ_GAS,
        )
        pim_version, pim_id, pim_count, pim_root = (
            decode_profile_ingress_membership_v2(pim_raw))
        pia_raw = self.manager.staticcall_profile_ingress_authorization_v2(
            PROFILE_INGRESS_AUTHORIZATION_SELECTOR
            + brx.bridge_authorization_id,
            caller=self.address, value=0,
            gas=PROFILE_INGRESS_AUTHORIZATION_READ_GAS,
        )
        pia_id, pia = decode_profile_ingress_authorization_v2(pia_raw)
        bip_raw = self.router.staticcall_bridge_invocation_policy_v1(
            BRIDGE_INVOCATION_POLICY_SELECTOR
            + _model_uint(version, 32, "BRC1 BIP1 version"),
            caller=self.address, value=0,
            gas=BRIDGE_INVOCATION_POLICY_READ_GAS,
        )
        bip = decode_bridge_invocation_policy_v1(bip_raw)
        descriptor = brx.source_descriptor_words
        adapter_address = pia[1][12:]
        factory = self.router._source_bridge_factories_by_address.get(
            "0x" + descriptor[0][12:].hex())
        expected_adapter_address = bridge_adapter_create2_address_v1(
            factory="0x" + descriptor[0][12:].hex(),
            protocol_version=version,
            source_descriptor_id=brx.source_bridge_execution_hash,
            configuration_hash=pia[3],
            source_bridge="0x" + descriptor[8][12:].hex(),
            credit_registry="0x" + descriptor[12][12:].hex(),
            router=self.router.address, queue=self.router.forced_queue.address,
            seal_authority=self.router.version_manager,
        )
        deployment = self.router._profile_deployments_by_version.get(
            version, {}).get(brx.bridge_authorization_id)
        expected_registration_commitment = keccak256(b"".join((
            D_DESTINATION_REGISTRATION,
            _model_uint(version, 8, "BRC1 registration version"),
            row.release_manifest_hash,
            _model_uint(
                _decode_uint_word_v1(pia[13], 256, "BRC1 destination"),
                32, "BRC1 registration destination"),
            brx.destination_namespace, pia[14], pia[15][12:], pia[17],
            row.execution_profile_hash,
        )))
        key = self._key_by_destination_chain_version.get((
            self.release_authority_descriptor.destination_chain_id, version
        ))
        entry = self.entries.get(key) if key is not None else None
        if (type(self.manager) is not ProtocolVersionManagerV1
                or mact.lifecycle
                    is not RouterMigrationLifecycle.ACTIVATING
                or mact.activation_context_hash == bytes(32)
                or active.phase is not RouterPhase.READY
                or active.generation != mact.generation
                or active.active_protocol_version
                    != mact.source_protocol_version
                or active.active_settlement != mact.source_settlement
                or active.target_protocol_version != version
                or active.target_protocol_version
                    != mact.target_protocol_version
                or active.target_manifest_hash
                    != mact.target_manifest_hash
                or active.target_registration_hash
                    != target_registration_hash
                or active.target_registration_hash
                    != mact.target_registration_hash
                or mact.target_protocol_version != version
                or mact.source_protocol_version
                    != row.expected_predecessor_protocol_version
                or mact.target_settlement != row.target_settlement
                or mact.target_manifest_hash != row.release_manifest_hash
                or mact.target_registration_hash
                    != target_registration_hash
                or row.target_registration_hash
                    != target_registration_hash
                or brx.protocol_version != version
                or pir_version != version or pim_version != version
                or bip.protocol_version != version
                or row.bridge_route_expansion_hash != keccak256(brx_raw)
                or pim_id != brx.bridge_authorization_id
                or pia_id != brx.bridge_authorization_id
                or pir_count != pim_count or pir_root != pim_root
                or brx.invocation_policy_hash != bip.invocation_policy_hash
                or brx.invocation_policy_count != len(bip.denied)
                or brx.destination_registration_commitment
                    != expected_registration_commitment
                or _decode_uint_word_v1(pia[0], 8, "BRC1 bridge kind")
                    != ForceKind.BRIDGE_CREDIT.value
                or pia[4][12:] != _model_address20(self.router.address)
                or pia[5] != _model_fixed_bytes32(self.router.runtime_hash)
                or pia[6]
                    != _model_fixed_bytes32(self.router.configuration_hash)
                or pia[7][12:]
                    != _model_address20(self.router.forced_queue.address)
                or pia[8]
                    != _model_fixed_bytes32(self.router.forced_queue.runtime_hash)
                or pia[9]
                    != _model_fixed_bytes32(self.router.forced_queue.config_hash)
                or pia[10] != brx.source_domain_id
                or pia[12] != brx.source_bridge_execution_hash
                or _decode_uint_word_v1(pia[13], 256,
                                        "BRC1 destination chain")
                    != self.release_authority_descriptor.destination_chain_id
                or pia[14] != (bytes(32) if key is None
                               else _model_fixed_bytes32(key[2]))
                or descriptor[18][12:] != _model_address20(self.address)
                or descriptor[19] != _model_fixed_bytes32(self.runtime_hash)
                or descriptor[20]
                    != _model_fixed_bytes32(self.configuration_hash)
                or type(deployment) is not BridgeAdapter
                or _model_address20(deployment.address) != adapter_address
                or _model_address20(expected_adapter_address) != adapter_address
                or type(factory) is not ImmutableV2BridgeFactory
                or _model_fixed_bytes32(factory.runtime_hash) != descriptor[1]
                or _model_fixed_bytes32(factory.configuration_hash)
                    != descriptor[2]
                or factory._adapters.get(expected_adapter_address)
                    is not deployment
                or _model_fixed_bytes32(deployment.runtime_hash) != pia[2]
                or _model_fixed_bytes32(deployment.configuration_hash) != pia[3]
                or _model_address20(deployment.queue_address) != pia[7][12:]
                or entry is None
                or entry.protocol_version != version
                or entry.target_settlement != row.target_settlement
                or entry.target_registration_hash != target_registration_hash
                or entry.release_manifest_hash != row.release_manifest_hash
                or entry.execution_profile_hash != row.execution_profile_hash
                or entry.bridge_route_expansion_hash
                    != row.bridge_route_expansion_hash
                or entry.rtr_hash != keccak256(
                    encode_target_release_registration_return_v2(row))
                or entry.brx_hash != keccak256(brx_raw)
                or entry.pir_hash != keccak256(pir_raw)
                or entry.pim_hash != keccak256(pim_raw)
                or entry.pia_hash != keccak256(pia_raw)
                or entry.bip_hash != keccak256(bip_raw)
                or entry.package_root != self._primitive_package_root_v2(
                    encode_target_release_registration_return_v2(row),
                    brx_raw, pir_raw, pim_raw, pia_raw, bip_raw)
                or entry.registration_commitment
                    != brx.destination_registration_commitment
                or entry.source_chain_id != brx.source_chain_id
                or entry.source_registration_epoch != _decode_uint_word_v1(
                    descriptor[27], 64, "BRC1 cached source epoch")
                or entry.source_domain_id != brx.source_domain_id
                or entry.bridge_execution_hash
                    != brx.source_bridge_execution_hash
                or entry.destination_chain_id
                    != _decode_uint_word_v1(
                        pia[13], 256, "BRC1 cached destination")
                or entry.destination_domain_id != pia[14]
                or entry.destination_bridge != pia[15][12:]
                or entry.invocation_policy_hash
                    != bip.invocation_policy_hash
                or entry.bridge_authorization_id
                    != brx.bridge_authorization_id
                or _model_address20(entry.adapter_address) != adapter_address
                or entry.adapter_runtime_hash != pia[2]
                or entry.adapter_configuration_hash != pia[3]
                or entry.source_bridge_address != descriptor[8][12:]
                or entry.source_credit_registry_address != descriptor[12][12:]
                or entry.source_quota_manager_address != descriptor[15][12:]
                or not self._primitive_entry_matches_rows_v2(
                    entry, row, brx, pir_raw, pim_raw, pia_raw, bip, bip_raw,
                    encode_target_release_registration_return_v2(row), brx_raw)
                or not self._primitive_package_exact(entry)
                or entry.arm_ready_consumed
                or clock.block_number < entry.staged_at_block
                    + BRIDGE_ROUTE_ARM_REVIEW_BLOCKS):
            raise ValueError("BRC1 MACT/RTR2/primitive join is inexact")
        if entry is None:
            raise ValueError("BRC1 package is not ARM_READY")
        entry.arm_ready_consumed = True
        result = b"".join((
            b"BRC1" + bytes(28),
            _model_uint(version, 32, "BRC1 version"),
            target_registration_hash,
            entry.package_root,
        ))
        if len(result) != CONSUME_BRIDGE_ROUTE_ARM_READY_RETURN_LENGTH:
            raise AssertionError("BRC1 return width drifted")
        return (
            result if self.consume_bridge_route_return_override is None
            else self.consume_bridge_route_return_override
        )

    def consume_arm_ready(
        self,
        registration: "SettlementRegistration",
        clock: Clock,
        *,
        router: "ActiveSettlementRouter",
        capability: object,
    ) -> bool:
        """Legacy-fixture compatibility; production uses executable BRC1."""

        frame = getattr(router, "_migration_callback_frame", None)
        if (router is not self.router
                or capability is not _BRIDGE_ROUTE_ACTIVATION_CAPABILITY
                or router.migration_lifecycle
                    is not RouterMigrationLifecycle.ACTIVATING
                or type(frame) is not MigrationCanonicalContextV2
                or frame.transition_kind != "VERSION_MIGRATION"
                or frame.source_protocol_version != router.active_version
                or frame.target_protocol_version
                    != getattr(getattr(registration, "settlement", None),
                               "protocol_version", 0)
                or frame.target_manifest_hash
                    != getattr(registration, "release_manifest_hash", b"")
                or frame.target_registration_hash
                    != target_registration_hash_v2(registration)
                or (
                    router.registrations.get(frame.target_protocol_version)
                        is not registration
                    and not (
                        frame.target_protocol_version
                            not in router.registrations
                        and frame.target_protocol_version
                            == registration.settlement.protocol_version
                    )
                )):
            return False
        entry = self.arm_ready_entry(
            registration,
            registration.release_manifest.destination_chain_id,
            clock,
        )
        if entry is None:
            return False
        entry.arm_ready_consumed = True
        return True

    def confirm(self, source_domain_id: str, execution_hash: str,
                destination_domain_id: str, *, clock: Clock,
                canonical_sequence: int,
                proof: CanonicalMptMembershipProof) -> bool:
        entry = self.entries.get(
            (source_domain_id, execution_hash, destination_domain_id))
        canonical = (
            None if entry is None else self.router.canonical_at(
                entry.protocol_version, canonical_sequence
            )
        )
        if (type(clock) is not Clock or entry is None
                or entry.confirmed_at_block is not None
                or canonical is None
                or clock.block_number
                    < canonical.canonicalized_at_block + F_L1
                or clock.block_number < entry.staged_at_block):
            return False
        try:
            statement = self.registration_storage_statement(
                source_domain_id,
                execution_hash,
                destination_domain_id,
                canonical_sequence=canonical_sequence,
            )
            result = self.registration_mpt_verifier.verify_membership(
                statement, proof
            )
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return False
        if (not self.registration_mpt_verifier.valid_result(result)
                or result.verifier is not self.registration_mpt_verifier
                or result.descriptor
                    != self.registration_mpt_verifier.descriptor
                or result.statement != statement
                or result.decoded_registrar_runtime_hash
                    != statement.registrar_code_hash
                or result.decoded_value
                    != statement.expected_value
                or result.returndata != bytes.fromhex(statement.digest)):
            return False
        entry.confirmed_at_block = clock.block_number
        self._confirmed_at_by_domain.setdefault(
            destination_domain_id, clock.block_number
        )
        return True

    def registration_storage_statement(
        self,
        source_domain_id: str,
        execution_hash: str,
        destination_domain_id: str,
        *,
        canonical_sequence: int,
    ) -> RegistrationStorageStatement:
        """Derive every membership statement field from pinned L1 history."""

        entry = self.entries.get(
            (source_domain_id, execution_hash, destination_domain_id)
        )
        canonical = (
            None if entry is None else self.router.canonical_at(
                entry.protocol_version, canonical_sequence
            )
        )
        if entry is None or canonical is None:
            raise ValueError("registration statement has no canonical entry")
        return RegistrationStorageStatement(
            self.router.settlement_chain_context_id,
            self.router.address,
            self.address,
            registration_route_key(
                source_domain_id, execution_hash, destination_domain_id
            ),
            self.release_authority_descriptor.destination_chain_id,
            entry.protocol_version,
            canonical_sequence,
            canonical.state_root,
            self.release_authority_descriptor.registrar_address,
            self.release_authority_descriptor.registrar_runtime_hash,
            terminal_registration_storage_trie_key(entry.protocol_version),
            entry.registration_commitment,
        )

    def final_entry(self, source_domain_id: str, execution_hash: str,
                    destination_domain_id: str,
                    clock: Clock) -> BridgeSupportEntry | None:
        entry = self.entries.get(
            (source_domain_id, execution_hash, destination_domain_id)
        )
        if (type(clock) is not Clock or entry is None
                or entry.confirmed_at_block is None
                or clock.block_number
                    < entry.confirmed_at_block + SUPPORT_FINALITY_BLOCKS):
            return None
        return entry

    def latest_final_entry(
        self,
        source_domain_id: str,
        execution_hash: str,
        destination_chain_id: int,
        clock: Clock,
        *,
        source_bridge: str,
        caller: str,
        target: str,
    ) -> BridgeSupportEntry | None:
        """Compatibility name routed through the exact ABR2 ABI boundary."""

        return self.active_route_entry(
            source_domain_id, execution_hash, destination_chain_id, clock,
            source_bridge=source_bridge, caller=caller, target=target,
        )

    def active_route_entry(
        self,
        source_domain_id: str,
        execution_hash: str,
        destination_chain_id: int,
        clock: Clock,
        *,
        source_bridge: str,
        caller: str,
        target: str,
    ) -> BridgeSupportEntry | None:
        """Call and decode ABR2, then rejoin its exact retained route row."""

        calldata = b"".join((
            ACTIVE_BRIDGE_ROUTE_SELECTOR,
            _model_uint(destination_chain_id, 32, "ABR2 destination chain"),
            bytes(12) + _model_address20(source_bridge),
            _model_fixed_bytes32(source_domain_id),
            _model_fixed_bytes32(execution_hash),
            bytes(12) + _model_address20(target),
        ))
        try:
            raw = self.active_bridge_route_v2(
                calldata, caller=caller, value=0,
                gas=ACTIVE_BRIDGE_ROUTE_READ_GAS, clock=clock,
            )
            route = decode_active_bridge_route_v2(raw)
        except (AttributeError, TypeError, ValueError, RuntimeError):
            return None
        key = self._key_by_destination_chain_version.get((
            destination_chain_id, route.active_protocol_version
        ))
        entry = self.entries.get(key) if key is not None else None
        if (entry is None or key[0] != source_domain_id
                or key[1] != execution_hash
                or entry.protocol_version != route.active_protocol_version
                or route.source_chain_id != entry.source_chain_id
                or route.source_registration_epoch
                    != entry.source_registration_epoch
                or route.source_domain_id != _model_fixed_bytes32(key[0])
                or route.bridge_execution_hash != _model_fixed_bytes32(key[1])
                or route.destination_domain_id != _model_fixed_bytes32(key[2])
                or route.destination_bridge
                    != entry.destination_bridge
                or route.release_manifest_hash != entry.release_manifest_hash
                or route.execution_profile_hash
                    != entry.execution_profile_hash
                or route.invocation_policy_hash
                    != entry.invocation_policy_hash
                or route.checked_target != _model_address20(target)):
            return None
        return entry

    def active_bridge_route_v2(
        self,
        calldata: bytes,
        *,
        caller: str,
        value: int,
        gas: int,
        clock: Clock,
    ) -> bytes:
        """Executable ABR2 boundary used identically by source and adapter."""

        if self.active_bridge_route_fault_point in {"revert", "oog"}:
            raise RuntimeError("injected ABR2 call fault")
        if (type(calldata) is not bytes
                or len(calldata) != ACTIVE_BRIDGE_ROUTE_CALLDATA_LENGTH
                or calldata[:4] != ACTIVE_BRIDGE_ROUTE_SELECTOR
                or not caller or value != 0
                or gas != ACTIVE_BRIDGE_ROUTE_READ_GAS
                or calldata[36:48] != bytes(12)
                or calldata[132:144] != bytes(12)):
            raise ValueError("ABR2 call envelope is noncanonical")
        destination_chain_id = int.from_bytes(calldata[4:36], "big")
        source_bridge_word = calldata[48:68]
        source_domain_word = calldata[68:100]
        execution_word = calldata[100:132]
        checked_target = calldata[144:164]
        if (destination_chain_id == 0
                or source_bridge_word == bytes(20)
                or source_domain_word == bytes(32)
                or execution_word == bytes(32)
                or checked_target == bytes(20)):
            raise ValueError("ABR2 call tuple is zero")
        entry = self._resolve_active_route_entry_v2(
            source_domain_word.hex(), execution_word.hex(),
            destination_chain_id, clock
        )
        if entry is None:
            raise ValueError("ABR2 route is not active")
        caller_is_source = (
            _model_address20(caller) == entry.source_bridge_address
            and source_bridge_word == entry.source_bridge_address
        )
        caller_is_adapter = (
            _model_address20(caller) == _model_address20(entry.adapter_address)
            and source_bridge_word == entry.source_bridge_address
        )
        if not (caller_is_source or caller_is_adapter):
            raise ValueError("ABR2 caller/source binding is inexact")
        decision = decode_bridge_invocation_decision_v1(
            self.router.staticcall_bridge_invocation_decision_v1(
                BRIDGE_INVOCATION_DECISION_SELECTOR
                + _model_uint(entry.protocol_version, 32, "BID1 version")
                + bytes(12) + checked_target,
                caller=self.address, value=0,
                gas=BRIDGE_INVOCATION_DECISION_READ_GAS,
            ))
        if decision != (
            entry.protocol_version, entry.invocation_policy_hash, False
        ):
            raise ValueError("ABR2 checked target is denied or policy drifted")
        result = encode_active_bridge_route_v2(ActiveBridgeRouteV2(
            entry.protocol_version,
            entry.source_chain_id,
            entry.source_registration_epoch,
            entry.source_domain_id,
            entry.bridge_execution_hash,
            entry.destination_domain_id,
            entry.destination_bridge,
            entry.release_manifest_hash,
            entry.execution_profile_hash,
            entry.invocation_policy_hash,
            checked_target,
        ))
        return (
            result if self.active_bridge_route_return_override is None
            else self.active_bridge_route_return_override
        )

    def _resolve_active_route_entry_v2(
        self,
        source_domain_id: str,
        execution_hash: str,
        destination_chain_id: int,
        clock: Clock,
    ) -> BridgeSupportEntry | None:
        """Resolve the semantic row only behind the executable ABR2 envelope."""

        if type(clock) is not Clock:
            return None
        try:
            # The order is normative and shares one fail-closed revert domain:
            # MACT must prove IDLE with an all-zero context before ASR1 is read.
            mact_raw = self.router.staticcall_migration_activation_context_v1(
                MIGRATION_ACTIVATION_CONTEXT_SELECTOR,
                caller=self.address, value=0,
                gas=BRIDGE_ACTIVE_ROUTE_MACT_GAS,
            )
            mact = decode_migration_activation_context_v1(mact_raw)
            if (BRIDGE_ACTIVE_ROUTE_MACT_GAS
                    != MIGRATION_ACTIVATION_CONTEXT_GAS
                    or len(mact_raw) != MIGRATION_ACTIVATION_CONTEXT_LENGTH
                    or mact.lifecycle is not RouterMigrationLifecycle.IDLE):
                return None
            raw = self.router.staticcall_active_settlement_state_v1(
                ACTIVE_SETTLEMENT_STATE_SELECTOR,
                caller=self.address, value=0,
                gas=BRIDGE_ACTIVE_ROUTE_ROUTER_STATE_GAS,
            )
            state = decode_active_settlement_state_v1(raw)
            version = state.active_protocol_version
            rtr_raw = self.router.staticcall_target_release_registration_v2(
                TARGET_RELEASE_REGISTRATION_SELECTOR
                + _model_uint(version, 32, "ABR2 RTR2 version"),
                caller=self.address, value=0,
                gas=TARGET_RELEASE_REGISTRATION_READ_GAS,
            )
            rtr = decode_target_release_registration_return_v2(rtr_raw)
            brx_raw = self.router.staticcall_bridge_route_expansion_v1(
                BRIDGE_ROUTE_EXPANSION_SELECTOR
                + _model_uint(version, 32, "ABR2 BRX1 version"),
                caller=self.address, value=0,
                gas=BRIDGE_ROUTE_EXPANSION_READ_GAS,
            )
            brx = decode_bridge_route_expansion_v1(brx_raw)
        except (AttributeError, TypeError, ValueError, RuntimeError):
            return None
        if (len(raw) != ACTIVE_SETTLEMENT_STATE_LENGTH
                or BRIDGE_ACTIVE_ROUTE_ROUTER_STATE_GAS
                    != ACTIVE_SETTLEMENT_STATE_GAS
                or state.phase is not RouterPhase.ACTIVE
                or state.active_protocol_version == 0
                or rtr.protocol_version != state.active_protocol_version
                or brx.protocol_version != state.active_protocol_version
                or rtr.bridge_route_expansion_hash != keccak256(brx_raw)):
            return None
        key = self._key_by_destination_chain_version.get((
            destination_chain_id, state.active_protocol_version
        ))
        entry = self.entries.get(key) if key is not None else None
        if (entry is None or key[0] != source_domain_id
                or key[1] != execution_hash
                or entry.protocol_version != state.active_protocol_version
                or entry.destination_chain_id != destination_chain_id
                or entry.target_settlement != state.active_settlement
                or entry.target_settlement != rtr.target_settlement
                or entry.release_manifest_hash != rtr.release_manifest_hash
                or entry.target_registration_hash
                    != rtr.target_registration_hash
                or entry.execution_profile_hash != rtr.execution_profile_hash
                or entry.rtr_hash != keccak256(rtr_raw)
                or entry.bridge_route_expansion_hash
                    != rtr.bridge_route_expansion_hash
                or entry.brx_hash != keccak256(brx_raw)
                or entry.bridge_authorization_id
                    != brx.bridge_authorization_id
                or entry.source_descriptor_id
                    != brx.source_bridge_execution_hash
                or entry.source_chain_id != brx.source_chain_id
                or entry.source_domain_id != brx.source_domain_id
                or entry.bridge_execution_hash
                    != brx.source_bridge_execution_hash
                or entry.registration_commitment
                    != brx.destination_registration_commitment
                or entry.invocation_policy_hash
                    != brx.invocation_policy_hash
                or entry.source_registration_epoch != _decode_uint_word_v1(
                    brx.source_descriptor_words[27], 64,
                    "ABR2 source registration epoch")
                or entry.source_bridge_address
                    != brx.source_descriptor_words[8][12:]
                or entry.source_credit_registry_address
                    != brx.source_descriptor_words[12][12:]
                or entry.source_quota_manager_address
                    != brx.source_descriptor_words[15][12:]
                or not (
                    self._primitive_package_exact(entry)
                    if entry.route_kind == "PRIMITIVE"
                    else self._package_exact(entry)
                        if entry.route_kind == "LEGACY" else False
                )):
            return None
        # Genesis/predecessor compatibility alone may use the older
        # destination-registration finality path.  Primitive successor rows
        # are unusable until BRC consumes ARM_READY in the activation journal.
        if entry.route_kind == "PRIMITIVE":
            return entry if entry.arm_ready_consumed else None
        if entry.route_kind == "LEGACY":
            return (
                entry if entry.arm_ready_consumed
                else self.final_entry(*key, clock)
            )
        return None

    def finalized_destination_manifest(
        self, destination_domain_id: str, clock: Clock
    ) -> "ReleaseManifestV2 | None":
        confirmed_at = self._confirmed_at_by_domain.get(destination_domain_id)
        manifest = self._destinations_by_domain.get(destination_domain_id)
        if (type(clock) is not Clock or confirmed_at is None
                or clock.block_number
                    < confirmed_at + SUPPORT_FINALITY_BLOCKS):
            return None
        return manifest

    def final(self, source_domain_id: str, execution_hash: str,
              destination_domain_id: str,
              clock: Clock) -> bool:
        return self.final_entry(
            source_domain_id, execution_hash, destination_domain_id, clock
        ) is not None

    def remove(self, source_domain_id: str, execution_hash: str,
               destination_domain_id: str) -> bool:
        _ = (source_domain_id, execution_hash, destination_domain_id)
        return False


@dataclass(frozen=True)
class FrozenBridgeFacade:
    bridge: str
    runtime_hash: str
    storage_layout_hash: str
    terminal_verifier: str

    def accepts(self, *, bridge: str, runtime_hash: str,
                storage_layout_hash: str, terminal_verifier: str) -> bool:
        return (bridge == self.bridge and runtime_hash == self.runtime_hash
                and storage_layout_hash == self.storage_layout_hash
                and terminal_verifier == self.terminal_verifier)

    @staticmethod
    def delegate_target() -> None:
        return None

    @staticmethod
    def upgrade(_new_runtime_hash: str) -> bool:
        return False


@dataclass(frozen=True)
class CanonicalTerminalCommitment:
    protocol_version: int
    execution_profile_hash: str
    canonical_sequence: int
    l2_block_number: int
    block_hash: str
    state_root: str
    terminal_root: str
    terminal_count: int
    canonicalized_at_block: int


def canonical_core_hash_v2(core: CanonicalCore) -> bytes:
    if type(core) is not CanonicalCore:
        raise ValueError("canonical core commitment requires exact core")
    narrow = (
        core.l2_block_number, core.tip_slot, core.message_cursor,
        core.next_excess_blob_gas, core.terminal_count,
    )
    if (not 0 <= core.l2_block_number < 1 << 48
            or any(type(value) is not int or not 0 <= value <= UINT64_MAX
                   for value in narrow[1:])
            or type(core.next_base_fee) is not int
            or not 0 <= core.next_base_fee <= SEAT_UINT256_MAX):
        raise ValueError("canonical core integer is out of range")
    return keccak256(b"".join((
        D_CANONICAL_CORE_V2,
        _model_uint(core.l2_block_number, 8, "canonical L2 block"),
        _model_fixed_bytes32(core.tip_hash),
        _model_uint(core.tip_slot, 8, "canonical tip slot"),
        _model_fixed_bytes32(core.state_root),
        _model_uint(core.message_cursor, 8, "canonical message cursor"),
        _model_fixed_bytes32(core.winning_data_commitment),
        _model_uint(core.next_base_fee, 32, "canonical next base fee"),
        _model_uint(
            core.next_excess_blob_gas, 8, "canonical next excess blob gas"
        ),
        _model_fixed_bytes32(core.terminal_root),
        _model_uint(core.terminal_count, 8, "canonical terminal count"),
    )))


def canonical_core_abi_v2(core: CanonicalCore) -> bytes:
    """Canonical 320-byte Solidity ABI tuple used by MCAN."""

    canonical_core_hash_v2(core)
    raw = b"".join((
        _model_uint(core.l2_block_number, 32, "ABI L2 block"),
        _model_fixed_bytes32(core.tip_hash),
        _model_uint(core.tip_slot, 32, "ABI tip slot"),
        _model_fixed_bytes32(core.state_root),
        _model_uint(core.message_cursor, 32, "ABI message cursor"),
        _model_fixed_bytes32(core.winning_data_commitment),
        _model_uint(core.next_base_fee, 32, "ABI next base fee"),
        _model_uint(core.next_excess_blob_gas, 32, "ABI blob gas"),
        _model_fixed_bytes32(core.terminal_root),
        _model_uint(core.terminal_count, 32, "ABI terminal count"),
    ))
    if len(raw) != 320:
        raise AssertionError("CanonicalCoreV2 ABI width drifted")
    return raw


def base_canonical_hash_v2(
    core: CanonicalCore, canonicalized_at_block: int,
) -> bytes:
    if not 0 <= canonicalized_at_block <= UINT64_MAX:
        raise ValueError("canonicalized block is out of range")
    return keccak256(
        D_BASE_CANONICAL_V2 + canonical_core_hash_v2(core)
        + _model_uint(canonicalized_at_block, 8, "canonicalized block")
    )


@dataclass(frozen=True)
class MigrationCanonicalContextV2:
    """Exact Router callback frame shared by freeze, adopt, and Queue migrate."""

    transition_kind: str
    router_generation: int
    seat_generation: int
    source_protocol_version: int
    target_protocol_version: int
    target_manifest_hash: bytes
    target_registration_hash: bytes
    source_checkpoint_id: bytes
    source_boundary_hash: bytes
    source_settlement: str
    target_settlement: str
    source_canonical_sequence: int
    target_canonical_sequence: int
    candidate_digest: str
    output_core: CanonicalCore
    output_core_hash: bytes
    canonicalized_at_block: int
    queue_start: int
    queue_end: int
    queue_address: str
    queue_root: str
    queue_count: int
    queue_credited_wei: int
    queue_post_accounted_liability_wei: int
    queue_post_total_claimable_wei: int
    beneficiary: str
    settlement_chain_id: int
    router_address: str
    source_manifest_hash: bytes
    base_canonical_hash: bytes
    statement_hash: bytes
    source_poststate_commitment: bytes

    def __post_init__(self) -> None:
        genesis = self.transition_kind == "GENESIS_IMPORT"
        if (self.transition_kind not in {"GENESIS_IMPORT", "VERSION_MIGRATION"}
                or self.router_generation < 0
                or not 0 < self.settlement_chain_id <= SEAT_UINT256_MAX
                or not self.router_address
                or not 0 <= self.seat_generation <= UINT64_MAX
                or (genesis and self.seat_generation != 0)
                or (not genesis and self.seat_generation == 0)
                or self.source_protocol_version < 0
                or self.target_protocol_version <= self.source_protocol_version
                or type(self.target_manifest_hash) is not bytes
                or len(self.target_manifest_hash) != 32
                or type(self.target_registration_hash) is not bytes
                or len(self.target_registration_hash) != 32
                or self.target_registration_hash == bytes(32)
                or type(self.source_manifest_hash) is not bytes
                or len(self.source_manifest_hash) != 32
                or self.source_manifest_hash == bytes(32)
                or type(self.base_canonical_hash) is not bytes
                or len(self.base_canonical_hash) != 32
                or self.base_canonical_hash == bytes(32)
                or type(self.statement_hash) is not bytes
                or len(self.statement_hash) != 32
                or self.statement_hash == bytes(32)
                or type(self.source_poststate_commitment) is not bytes
                or len(self.source_poststate_commitment) != 32
                or (genesis and self.source_poststate_commitment == bytes(32))
                or type(self.source_checkpoint_id) is not bytes
                or len(self.source_checkpoint_id) != 32
                or type(self.source_boundary_hash) is not bytes
                or len(self.source_boundary_hash) != 32
                or (genesis and (
                    self.source_checkpoint_id == bytes(32)
                    or self.source_boundary_hash == bytes(32)
                ))
                or (not genesis and (
                    self.source_checkpoint_id != bytes(32)
                    or self.source_boundary_hash != bytes(32)
                ))
                # GENESIS_IMPORT is an authority migration from the exact
                # compatibility proxy, never from address(0).
                or not self.source_settlement
                or not self.target_settlement
                or self.source_settlement == self.target_settlement
                or (genesis and self.source_canonical_sequence != 0)
                or (not genesis and self.source_canonical_sequence < 0)
                or self.target_canonical_sequence
                    != (0 if genesis else self.source_canonical_sequence + 1)
                or not self.candidate_digest
                or type(self.output_core) is not CanonicalCore
                or self.output_core_hash != canonical_core_hash_v2(self.output_core)
                or self.canonicalized_at_block <= 0
                or not self.queue_address or not self.queue_root
                or not 0 <= self.queue_start <= self.queue_end
                    <= self.queue_count
                or min(
                    self.queue_credited_wei,
                    self.queue_post_accounted_liability_wei,
                    self.queue_post_total_claimable_wei,
                ) < 0
                or not self.beneficiary):
            raise ValueError("migration canonical callback context is invalid")
        if not genesis:
            expected_source_poststate = keccak256(b"".join((
                D_SOURCE_FREEZE_POSTSTATE_V1,
                self.commitment,
                _model_address20(self.source_settlement),
                _model_uint(4, 1, "frozen source mode"),
                _model_uint(
                    self.router_generation, 8, "source freeze generation"
                ),
                _model_uint(
                    self.source_protocol_version, 8,
                    "source freeze protocol version",
                ),
                _model_uint(
                    self.source_canonical_sequence, 8,
                    "source freeze canonical sequence",
                ),
                self.base_canonical_hash,
                _model_uint(
                    self.canonicalized_at_block, 8, "source frozen block"
                ),
            )))
            if self.source_poststate_commitment not in {
                bytes(32), expected_source_poststate
            }:
                raise ValueError("source freeze poststate commitment is inexact")
            object.__setattr__(
                self, "source_poststate_commitment", expected_source_poststate
            )

    @property
    def commitment(self) -> bytes:
        transition_kind = 1 if self.transition_kind == "GENESIS_IMPORT" else 2
        return keccak256(b"".join((
            D_L1_ACTIVATION_CONTEXT_V1,
            _model_uint(self.settlement_chain_id, 32, "activation chain"),
            _model_address20(self.router_address),
            _model_uint(transition_kind, 1, "activation kind"),
            _model_uint(self.router_generation, 8, "activation generation"),
            _model_uint(self.seat_generation, 8, "activation seat generation"),
            _model_uint(
                self.source_protocol_version, 8, "activation source version"
            ),
            _model_uint(
                self.target_protocol_version, 8, "activation target version"
            ),
            self.source_manifest_hash,
            self.target_manifest_hash,
            self.target_registration_hash,
            _model_address20(self.source_settlement),
            _model_address20(self.target_settlement),
            _model_uint(
                self.source_canonical_sequence, 8, "activation source sequence"
            ),
            self.base_canonical_hash,
            self.statement_hash,
            _model_fixed_bytes32(self.candidate_digest),
            self.output_core_hash,
            _model_uint(
                self.target_canonical_sequence, 8, "activation target sequence"
            ),
            _model_address20(self.queue_address),
            _model_fixed_bytes32(self.queue_root),
            _model_uint(self.queue_count, 8, "activation Queue count"),
            _model_uint(self.queue_start, 8, "activation start cursor"),
            _model_uint(self.queue_end, 8, "activation end cursor"),
            _model_address20(self.beneficiary),
            _model_uint(
                self.canonicalized_at_block, 8, "activation canonicalized block"
            ),
        )))

    @property
    def target_poststate_commitment(self) -> bytes:
        transition_kind = 1 if self.transition_kind == "GENESIS_IMPORT" else 2
        return keccak256(b"".join((
            D_L1_ADOPTION_V1,
            _model_uint(self.settlement_chain_id, 32, "adoption chain"),
            _model_address20(self.router_address),
            _model_address20(self.target_settlement),
            self.commitment,
            _model_uint(transition_kind, 1, "adoption kind"),
            _model_uint(self.router_generation, 8, "adoption generation"),
            _model_uint(
                self.source_protocol_version, 8, "adoption source version"
            ),
            _model_uint(
                self.target_protocol_version, 8, "adoption target version"
            ),
            _model_uint(
                self.source_canonical_sequence, 8, "adoption source sequence"
            ),
            self.target_manifest_hash,
            _model_fixed_bytes32(self.candidate_digest),
            self.output_core_hash,
            _model_uint(
                self.target_canonical_sequence, 8, "adoption target sequence"
            ),
            _model_uint(
                self.canonicalized_at_block, 8, "adoption canonicalized block"
            ),
        )))

    @property
    def queue_poststate_commitment(self) -> bytes:
        return keccak256(
            D_QUEUE_MIGRATION_POSTSTATE_V1
            + self.commitment
            + _model_address20(self.queue_address)
            + _model_address20(self.target_settlement)
            + _model_fixed_bytes32(self.queue_root)
            + _model_uint(self.queue_count, 8, "Queue count")
            + _model_uint(self.queue_end, 8, "Queue end")
            + _model_address20(self.beneficiary)
            + _model_uint(self.queue_credited_wei, 32, "Queue credited wei")
            + _model_uint(
                self.queue_post_accounted_liability_wei, 32,
                "Queue post liability",
            )
            + _model_uint(
                self.queue_post_total_claimable_wei, 32,
                "Queue post pull claimable",
            )
        )

    @property
    def target_return(self) -> bytes:
        return b"".join((
            MIGRATION_CANONICAL_MAGIC + bytes(28),
            bytes(24) + _model_uint(
                self.target_canonical_sequence, 8,
                "target canonical sequence",
            ),
            self.target_poststate_commitment,
        ))

    @property
    def adopt_calldata(self) -> bytes:
        transition_kind = 1 if self.transition_kind == "GENESIS_IMPORT" else 2
        raw = b"".join((
            MIGRATION_CANONICAL_ADOPT_SELECTOR,
            _model_uint(transition_kind, 32, "MCAN transition kind"),
            _model_uint(self.router_generation, 32, "MCAN generation"),
            _model_uint(self.seat_generation, 32, "MCAN seat generation"),
            _model_uint(
                self.source_protocol_version, 32, "MCAN source version"
            ),
            _model_uint(
                self.target_protocol_version, 32, "MCAN target version"
            ),
            _model_uint(
                self.source_canonical_sequence, 32, "MCAN source sequence"
            ),
            self.target_manifest_hash,
            _model_fixed_bytes32(self.candidate_digest),
            canonical_core_abi_v2(self.output_core),
        ))
        if len(raw) != 580:
            raise AssertionError("MCAN calldata width drifted")
        return raw

    @property
    def freeze_calldata(self) -> bytes:
        raw = MIGRATION_SOURCE_FREEZE_SELECTOR + self.commitment
        if len(raw) != 36:
            raise AssertionError("MFRZ calldata width drifted")
        return raw

    @property
    def queue_calldata(self) -> bytes:
        raw = b"".join((
            MIGRATION_QUEUE_SELECTOR,
            self.commitment,
            bytes(12) + _model_address20(self.source_settlement),
            bytes(12) + _model_address20(self.target_settlement),
            _model_fixed_bytes32(self.queue_root),
            _model_uint(self.queue_count, 32, "QMIG Queue count"),
            _model_uint(self.queue_start, 32, "QMIG start cursor"),
            _model_uint(self.queue_end, 32, "QMIG end cursor"),
            bytes(12) + _model_address20(self.beneficiary),
        ))
        if len(raw) != 260:
            raise AssertionError("QMIG calldata width drifted")
        return raw

    @property
    def maps_calldata(self) -> bytes:
        raw = MIGRATION_POST_STATE_SELECTOR + self.commitment
        if len(raw) != 36:
            raise AssertionError("MAPS calldata width drifted")
        return raw

    @property
    def source_return(self) -> bytes:
        return b"".join((
            MIGRATION_SOURCE_FREEZE_MAGIC + bytes(28),
            self.commitment,
            self.source_poststate_commitment,
        ))

    @property
    def queue_return(self) -> bytes:
        return b"".join((
            MIGRATION_QUEUE_MAGIC + bytes(28),
            self.commitment,
            _model_uint(
                self.queue_credited_wei, 32, "migration Queue credited wei"
            ),
            self.queue_poststate_commitment,
        ))

    @property
    def source_maps_return(self) -> bytes:
        return self._maps_return(1, self.source_return[64:96])

    @property
    def target_maps_return(self) -> bytes:
        return self._maps_return(2, self.target_poststate_commitment)

    @property
    def queue_maps_return(self) -> bytes:
        return self._maps_return(3, self.queue_poststate_commitment)

    def _maps_return(self, role: int, poststate: bytes) -> bytes:
        return b"".join((
            MIGRATION_ADOPTION_STATE_MAGIC + bytes(28),
            _model_uint(role, 32, "migration MAPS role"),
            self.commitment,
            poststate,
        ))

    @property
    def maps_return(self) -> bytes:
        return self.target_maps_return


class LegacyLaunchPhase(Enum):
    ACTIVE = 0
    DRAINING = 1
    QUIESCENT = 2
    READY = 3
    FROZEN = 4


LEGACY_GENESIS_STATE_MAGIC = b"LGS1"
LEGACY_GENESIS_ARM_MAGIC = b"LGAR"
LEGACY_GENESIS_FINALIZE_MAGIC = b"LGFN"
LEGACY_GENESIS_STATE_LENGTH = 512
GENESIS_CAMPAIGN_MAGIC = b"LGC1"
GENESIS_CAMPAIGN_STATE_LENGTH = 512
LEGACY_GENESIS_PREPARATION_MAGIC = b"LGPR"
LEGACY_GENESIS_BEGIN_SCAN_MAGIC = b"LGBS"
LEGACY_GENESIS_SCAN_PROPOSALS_MAGIC = b"LGSP"
LEGACY_GENESIS_SCAN_FORCED_MAGIC = b"LGSF"
LEGACY_GENESIS_SCAN_STATE_MAGIC = b"LGSS"
LEGACY_GENESIS_QUIESCENCE_MAGIC = b"LGQS"
LEGACY_GENESIS_RESUME_MAGIC = b"LGRS"
LEGACY_GENESIS_EXPIRE_MAGIC = b"LGEX"
LEGACY_GENESIS_CAMPAIGN_DOMAIN = b"slot-chain-legacy-genesis-campaign-v1"
LEGACY_GENESIS_BOUNDARY_DOMAIN = b"slot-chain-legacy-genesis-boundary-v1"
LEGACY_GENESIS_ARM_DOMAIN = b"slot-chain-legacy-genesis-arm-v1"
LEGACY_GENESIS_LAUNCH_DOMAIN = b"slot-chain-legacy-genesis-launch-v1"
LEGACY_GENESIS_POSTSTATE_DOMAIN = b"slot-chain-legacy-genesis-poststate-v1"


